'use strict';
let financeRange=24,dexLimit=60,dexFilters={style:'all',distance:'all',surface:'all',rarity:'all',effect:'all',apt:5,generic:false},guideTrack=null,guideCourse=null,guideOptions={style:0,season:1,weather:1,ground:1,time:2};
let DB,E,S,view='home',selected=null,tab='profile',raceTurn=null,scoutTab='uma',supportFilter='all',dexTab='outfits',search='',busy=false,lastDraw=[],rankStage='junior',rankDisc='all',starterPreview=null;
const $=q=>document.querySelector(q),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>(n<0?'−₩':'₩')+Math.abs(Math.round(n)).toLocaleString('ko-KR'),KEY='tracen-fm.career.v1',BACKUP=KEY+'.backup';
const VIEWS=[['home','홈','◈'],['news','뉴스','▤'],['races','레이스','⚑'],['ranking','랭킹','↗'],['farmRanking','목장 랭킹','⌂'],['rivals','라이벌','⇄'],null,['runners','우마무스메','♞'],['training','트레이닝','✧'],['awards','JRA 시상식','★'],['medical','메디컬','✚'],['supports','서포트 카드','▣'],['fusion','서포트 합성','◇'],['factors','인자','✦'],['scout','스카우트','⌕'],null,['finance','재정','₩'],['shop','상점','▢'],['facilities','시설','▥'],['hall','기록실','♜'],['dex','도감','▧']];
const direction=r=>r.direction===1?'우회전':r.direction===2?'좌회전':'직선';
const statNames=UmaFM.STATS,aptNames=UmaFM.APTN,styleNames=UmaFM.STYLES;
function date(t=S.turn,y=S.year){return `${2026+y}년 ${Math.floor(t/2)+1}월 ${t%2?'후반':'전반'} · 목장 ${y}년차`}
function image(o,cls='',art=false){return `<img class="${cls}" src="${esc(art?(o.art||o.image):o.image)}" alt="${esc(o.characterKo||o.koCharacter||o.ko)}" loading="lazy">`}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function persist(){if(!S)return Promise.resolve();S.savedAt=Date.now();const state=S;return CareerStore.write(KEY,state).catch(e=>{console.error(e);toast('자동 저장에 실패했습니다. 저장 파일을 내보내 주세요.');throw e})}
function showModal(html){stopRacePresentation();$('#modal').classList.remove('race-modal');$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0}
function closeModal(){stopRacePresentation();$('#modal').classList.remove('race-modal');$('#modal').close()}
function chip(t,cls=''){return `<span class="tag ${cls}">${t}</span>`}
function button(label,action,extra='',cls=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`}
function empty(t){return `<div class="empty"><span>◇</span>${t}</div>`}
function rankGrade(v){return `<strong class="grade g-${v[0]}">${esc(v)}</strong>`}
function skillIcon(s){return `<img class="skill-icon" src="images/skills/${s.icon}.png" alt="" loading="lazy">`}
function skillButton(id,extra=''){const s=E.skills.get(Number(id));return s?`<button class="skill-pill rarity-${s.rarity}" data-action="skill" data-id="${s.id}">${skillIcon(s)}<span>${esc(s.name)}</span>${skillCategoryBadges(s.id)}${extra}</button>`:''}
function name(u){return E.o(u).characterKo}
function runnerHead(u,ageBadge=false){const o=E.o(u);return `<div class="runner-identity">${image(o,'avatar')}<div><b>${esc(name(u))}</b>${ageBadge?`<span class="activity-age-badge">${esc(E.ageName(S,u))}</span>`:''}<small>${esc(o.ko)}</small></div></div>`}
function statGrid(u){return `<div class="stat-grid">${E.baseStats(u).map((v,i)=>`<div><small>${statNames[i]}</small><strong class="stat-number">${v}<em>/100</em></strong><div class="stat-track"><i style="width:${v}%"></i></div></div>`).join('')}</div>`}
function runnerCard(u,compact=false){return `<article class="runner-card ${compact?'compact':''}"><button class="runner-top" data-action="runner" data-id="${u.id}">${runnerHead(u)}<span class="arrow">↗</span></button><div class="runner-tags">${chip(E.ageName(S,u))}${chip(u.injury?'치료 '+u.injury+'턴':'컨디션 '+u.fitness,u.injury?'danger':'')}${chip(u.wins+'승 · 팬 '+u.fans.toLocaleString())}</div>${statGrid(u)}<div class="runner-bottom"><span>${u.status==='undebuted'?'6월 신마전 대기 · 훈련 제한':u.entry?'⚑ 출전 등록':u.plan==='rest'?'☾ 휴식':(u.autoState||'자동 관리')+' · 미분배 '+u.evPoints+' Pt / 노력치 '+u.ev.reduce((a,b)=>a+b,0)+'/200'}</span><b>${u.sp} Pt</b></div></article>`}
function shell(){const title=VIEWS.find(v=>v?.[0]===view)?.[1]||'홈';return `<aside class="sidebar"><a class="brand" href="#" data-action="nav" data-view="home"><span class="brand-mark">T<span>✦</span></span><div>TRACEN <b>FM</b><small>UMA MUSUME RANCH MANAGER</small></div></a><div class="club-mark"><span class="club-logo">${esc(S.club[0])}</span><div><b>${esc(S.club)}</b><small>RANCH MANAGEMENT · SEASON ${String(S.year).padStart(2,'0')}</small></div></div><nav aria-label="주 메뉴">${VIEWS.map(v=>v?`<button class="nav-item ${view===v[0]?'active':''}" data-action="nav" data-view="${v[0]}"><span>${v[2]}</span>${v[1]}${navNoticeHTML(v[0])}${v[0]==='runners'?`<small>${E.active(S).length}/4</small>`:''}</button>`:'<div class="nav-divider"></div>').join('')}</nav><div class="sidebar-bottom">${button('운영 가이드','rules','','text')}${button('팬게임 및 권리 안내','fanNotice','','text')}${button('커리어 관리','career','','text')}${button('저장 내보내기','export','','text')}${button('저장 불러오기','import','','text')}<p>● 자동 저장 · 이 브라우저<br>비공식 팬게임</p></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">TRACEN / <b>${title}</b></div><div class="topbar-right"><span class="saved">● 저장됨</span>${button('⚙ 규칙','rules','','text')}<span class="manager-avatar">${esc(S.club[0])}</span></div></header><main><div class="page-heading"><div><span class="eyebrow">${view==='home'?'YOUR NEXT CHAPTER':'TRACEN MANAGEMENT'}</span><h1>${title}<span class="season-tag">SEASON ${String(S.year).padStart(2,'0')}</span></h1><p>${date()} <span class="muted">/ 24턴 시즌</span></p></div><div class="heading-actions">${S.lastReport?button('직전 결산','report','','text'):''}<select id="fastAdvance" aria-label="여러 턴 진행"><option value="">빠른 진행</option><option value="2">2턴 진행</option><option value="4">4턴 진행</option><option value="debut">6월 신마전까지 준비</option></select>${button(S.pendingTurn?'레이스 결과 확인':'턴 진행 →','advance','',busy?'disabled':'primary')}</div></div><div class="top-metrics"><div><small>운영 자금</small><strong class="${S.funds<0?'red':''}">${money(S.funds)}</strong></div><div><small>목장 명성</small><strong>${S.fame}<em>REP</em></strong></div><div><small>목장 소속 · 현역 ${E.active(S).length}/4</small><strong>${E.rosterCount(S)}<em>/ 10</em></strong></div><div><small>서포트 뽑기권</small><strong>${S.tickets}<em>TICKETS</em></strong></div><div><small>월 생활·시설비</small><strong>${money(E.upkeepBreakdown(S).total)}</strong></div></div>${E.debt(S)>0?`<div class="debt-banner"><b>채무 ${money(E.debt(S))}</b> · 상금과 팬 수익으로 상환할 때까지 구매·입찰·유료 서비스가 제한됩니다. 필수 생활·시설비는 계속 정산됩니다.</div>`:''}<div id="page">${pages[view]()}${view==='races'?resultsPanel():''}${view==='home'?nearbyRivalsHTML(E.own(S)[0]):''}</div><footer>TRACEN FM · 일본 서버 데이터 기반 · ${DB.outfits.length} 의상 / ${DB.supports.length} 서포트 / ${DB.skills.length.toLocaleString()} 스킬<br>게임 고유의 24턴 운영·성장·출전 심사·레이스 시뮬레이션 규칙을 적용합니다. <button data-action="rules">규칙 확인 ↗</button></footer></main></div>`}
function panel(title,body,action=''){return `<section class="panel"><div class="panel-heading"><h2>${title}</h2>${action}</div>${body}</section>`}
function raceTable(races,mini=false){return races.length?`<div class="table-wrap"><table><thead><tr><th>레이스</th><th>코스</th><th>대상</th>${mini?'':'<th>조건</th>'}<th></th></tr></thead><tbody>${races.map(r=>`<tr><td><span class="race-grade grade-${r.grade}">${E.gradeName(r)}</span><b>${esc(r.name)}</b></td><td>${esc(r.track)}<small>${r.terrain===2?'더트':'잔디'} ${r.distance}m · ${direction(r)}</small></td><td>${r.ages.map(a=>['','주니어','클래식','시니어'][a]).join(' · ')}</td>${mini?'':`<td><small>팬 ${E.requiredFans(r).toLocaleString()}명 이상</small></td>`}<td>${button('상세 ↗','race','data-key="'+esc(r.key)+'" data-turn="'+(raceTurn??S.turn)+'"','small')}</td></tr>`).join('')}</tbody></table></div>`:empty('이번 기간에는 등록된 레이스가 없습니다.')}
function homePage(){const team=E.own(S),hero=team.find(u=>u.entry)||team[0],races=E.racesAt(S),eligible=races.filter(r=>team.some(u=>E.projectRace(S,u,r,E.abs(S)).ok));const first=eligible[0];return `<section class="season-hero"><div class="hero-copy"><span class="eyebrow light">THE ROAD TO THE WINNING LIVE</span><h2>다음 승리는,<br>우리의 선택에서.</h2><p>${first?`이번 턴 추천 무대 · ${esc(first.name)}<br>${esc(first.track)} ${first.distance}m · ${first.terrain===2?'더트':'잔디'}`:'새로운 시즌, 차근차근 준비할 시간.<br>훈련과 스카우트로 목장의 내일을 설계하세요.'}</p><div class="hero-actions">${button(first?'출전 계획 세우기':'소속 관리하기','nav','data-view="'+(first?'races':'runners')+'"','lime')}${button('스카우트 보고서 ↗','nav','data-view="scout"','ghost')}</div></div><div class="hero-art"><div class="track-lines"></div><div class="hero-number">${String(S.year).padStart(2,'0')}</div>${hero?image(E.o(hero),'hero-uma',true):''}<span class="art-caption">${hero?esc(name(hero))+' / '+esc(E.o(hero).ko):'TRACEN ACADEMY'}</span></div></section><div class="dashboard-row"><div class="section-label"><h2>목장 소속 <small>${team.length} / 4</small></h2>${button('우마무스메 관리 ↗','nav','data-view="runners"','text')}</div><div class="runner-grid">${team.map(u=>runnerCard(u,true)).join('')}${team.length<4?`<button class="add-runner" data-action="nav" data-view="scout"><span>＋</span><b>새로운 가능성을 찾아서</b><small>데뷔 전 우마무스메 스카우트</small></button>`:''}</div></div><div class="two-columns"><div>${panel('이번 턴 체크리스트',`<div class="checklist">${team.filter(u=>E.factorWindow(S,u)).map(u=>`<button data-action="runner" data-id="${u.id}" data-tab="factors"><i>✦</i><span><b>${esc(name(u))} 계승 가능</b><small>${'해당 연차 내 언제든 인자 사용 가능'}</small></span><em>↗</em></button>`).join('')}<button data-action="nav" data-view="supports"><i>▣</i><span><b>서포트 카드 ${Object.values(S.supports).reduce((a,b)=>a+b,0)}장 보유</b><small>서포트 영구 장착 · 내장 스킬 등록</small></span><em>↗</em></button><button data-action="nav" data-view="scout"><i>⌕</i><span><b>스카우트 보고서 ${S.scouts.length}건</b><small>목장 10명 · 현역 4명</small></span><em>↗</em></button>${team.filter(u=>u.injury).map(u=>`<button data-action="nav" data-view="medical"><i>✚</i><span><b>${esc(name(u))} 치료 중</b><small>${u.injury}턴 남음</small></span><em>↗</em></button>`).join('')}</div>`)}</div><div>${panel('트레센 브리핑',`<div class="news-feed">${S.news.slice(0,4).map(newsItem).join('')}</div>`,button('뉴스 전체 ↗','nav','data-view="news"','text'))}</div></div>${panel('이번 턴 레이스',raceTable(eligible.slice(0,5),true),chip(eligible.length+'개 출전 검토 가능'))}`}
function newsItem(n){const runner=n.runner==null?null:S.runners.find(u=>u.id===n.runner)||S.recordArchive?.[n.runner];const own=n.runner!=null&&(n.team===0||E.wasPlayerOwned(runner));return `<article class="news-item editorial ${own?'player-news':''} ${n.majorAchievement?'major-achievement-news':''}">${n.image?`<img class="news-portrait" src="${esc(n.image)}" alt="${esc(n.title)}" loading="lazy">`:''}<div><div class="news-byline"><small>${date(n.at%24,Math.floor(n.at/24)+1)} · ${n.playerRelated?'MY RANCH · ':''}${esc(n.author||'트레센 경마신문')}</small>${n.majorAchievement?'<span class="major-news-label">'+esc(n.achievementLabel)+(n.recovered?' · 기록 복원':'')+'</span>':''}</div><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p>${n.entrantIds?.length?'<small>'+(n.kind==='preview'?'확정 출전 명단 연동':'레이스 결과 연동')+' · 우마무스메 '+n.entrantIds.length+'명</small>':''}${[...(n.raceLinks||[]),...(n.achievementLinks||[])].filter((x,i,a)=>a.findIndex(y=>y.result===x.result)===i&&S.results.some(r=>r.id===x.result)).map(x=>button(esc(x.race)+' 결과','result','data-id="'+x.result+'"','small')).join('')}${n.result&&S.results.some(r=>r.id===n.result)?button('실제 경기 결과 →','result','data-id="'+n.result+'"','small'):''}${n.runner?button('우마무스메 기록',S.runners.some(u=>u.id===n.runner)?'runner':'historicalRunner','data-id="'+n.runner+'" data-tab="record"','small'):''}</div></article>`}
function missionHTML(){return `<div class="missions">${[['start3','레이스 3회 출전',S.missions.starts,3,3],['win1','레이스 1승',S.missions.wins,1,5],['turn6','목장 운영 6턴',S.missions.turns,6,4],['squad4','소속 4명',E.own(S).length,4,5]].map(([k,n,v,max,t])=>`<div class="mission"><div><b>${n}</b><small>${Math.min(v,max)}/${max} · 뽑기권 ${t}장</small></div>${S.missions.claims.includes(k)?chip('수령 완료'):button('보상 받기','mission',`data-key="${k}" ${v<max?'disabled':''}`,'small')}</div>`).join('')}</div>`}
function runnersPage(){const groups=[['undebuted','미데뷔 우마무스메','6월 신마전 준비 · 서포트 등록과 인자 계승 가능 · 노력치 훈련 불가'],['active','현역 우마무스메','자동 훈련으로 포인트 획득 · 수동 분배 · 1명당 1턴 1경기'],['retired','은퇴 우마무스메','현역 활동 종료 · 기록실과 영구 인자']];return groups.map(([status,title,desc])=>{const rows=S.runners.filter(u=>u.team===0&&u.status===status);return panel(title+' · '+rows.length,`<p class="note">${desc}</p><div class="runner-grid full">${rows.map(u=>runnerCard(u)).join('')}</div>${rows.length?'':empty('해당 상태의 소속 우마무스메가 없습니다.')}`)}).join('')+`<p class="note">목장은 10명, 현역은 4명까지 소속됩니다. 플레이어 시니어 2/3/4년차에는 실전 능력치가 5/10/15% 감소합니다. 시니어 4년차 종료 시 자동 은퇴합니다.</p>`}
function aptitudeHTML(u){return `<div class="apt-grid">${[['경기장',0,2],['거리',2,6],['각질',6,10]].map(([n,a,b])=>`<div><b>${n}</b>${u.apt.slice(a,b).map((v,i)=>`<span>${aptNames[a+i]}${rankGrade(UmaFM.apt(v))}</span>`).join('')}</div>`).join('')}</div>`}
function openRunner(id,which=tab){const u=S.runners.find(u=>u.id===Number(id));if(!u)return;selected=u.id;tab=which;const o=E.o(u),owned=u.team===0&&!u.retired,bonus=E.supportBonus(u);showModal(`<div class="runner-detail"><div class="runner-detail-head">${image(o,'detail-stand',true)}<div><span class="eyebrow">RANCH UMA MUSUME</span><h2>${esc(name(u))}</h2><p>${esc(o.ko)}</p><div class="tags">${chip(E.ageName(S,u))}${chip('개체값 '+E.ivStars(u.iv)+'★ · 합계 '+u.iv.reduce((n,v)=>n+v,0)+'/150')}${chip(u.starts+'전 '+u.wins+'승')}${chip('팬 '+u.fans.toLocaleString())}${E.decline(S,u)<1?chip('노쇠 -'+Math.round((1-E.decline(S,u))*100)+'%','warn'):''}</div><div class="runner-detail-state"><span>컨디션 <b>${u.fitness}</b></span><span>피로 <b>${u.fatigue}</b></span><span>스킬 Pt <b>${u.sp}</b></span></div>${qualificationHTML(u)}${owned&&u.status==='undebuted'?button('방출 · 보상 없음','releasePrompt','data-id="'+u.id+'"','small danger-outline'):''}${owned?button('은퇴 · 인자 등록','retire',`data-id="${u.id}" ${E.canRetire(S,u)?'':'disabled'}`,'small danger-outline'):''}</div></div><div class="tabs">${[['profile','능력·포인트 분배'],['supports','서포트 장착'],['skills','획득 스킬'],['factors','인자 계승'],['record','레이스 기록'],['titles','보유 타이틀']].map(([v,n])=>button(n,'runnerTab',`data-tab="${v}"`,v===tab?'active':'')).join('')}</div>${tab==='profile'?`${statGrid(u)}<div class="table-wrap"><table><thead><tr><th>능력</th><th>고정 개체값</th><th>노력치</th><th>서포트</th><th>청인자</th><th>기초능력</th></tr></thead><tbody>${statNames.map((n,i)=>`<tr><td>${n}</td><td>${u.iv[i]} <small>${E.ivDescription(u.iv[i])}</small></td><td>${u.ev[i]}</td><td>+${bonus[i]}</td><td>+${u.factorBonus[i]}</td><td>${E.baseStats(u)[i]}</td></tr>`).join('')}</tbody></table></div>${owned?runnerEVHTML(u):''}<h3 class="subheading">적성</h3>${aptitudeHTML(u)}<h3 class="subheading">고유기 · 자동 활성</h3><div class="skill-pills">${o.uniqueSkills.slice(-1).map(skillWithDescription).join('')}</div><h3 class="subheading">장착 스킬 · ${u.equipped.length}/8</h3><div class="skill-pills">${Array.from({length:8},(_,i)=>u.equipped[i]?skillButton(u.equipped[i]):chip('빈 슬롯 '+(i+1))).join('')}</div><h3 class="subheading">계승 고유기 · 별도 장착 ${u.inheritEquipped.length}/3</h3><div class="skill-pills">${u.inheritEquipped.map(skillWithDescription).join('')||'장착 없음'}</div>`:tab==='supports'?runnerSupports(u,owned):tab==='skills'?runnerSkills(u,owned):tab==='factors'?runnerFactors(u,owned):tab==='titles'?runnerTitlesHTML(u):runnerRecords(u)}</div>`)}
function runnerSkills(u,owned){const o=E.o(u),available=u.known.filter(i=>!u.learned.includes(i)&&!u.learned.some(k=>E.ancestors(k).has(i))),row=(id,known)=>{const s=E.skills.get(id);if(!s)return '';const gate=known?E.skillGate(u,id):{ok:true},price=E.skillPrice(u,id);return `<div class="skill-row ${known&&!gate.ok?'skill-locked':''}">${skillButton(id)}${skillDescriptionToggle(id)}<span class="skill-state">${s.rarity===6?'진화':s.rarity===2?'레어':'노말'}${known?' · '+price.cost+' Pt'+(price.discount?' <b class="support-discount">'+price.discount+'% 할인</b> <small class="skill-original-cost">'+price.base+' Pt</small>':''):' · 습득 완료'}${known&&!gate.ok?'<small class="skill-lock-reason">'+esc(gate.why)+'</small>':''}</span>${owned?button(known?gate.ok?'습득':'🔒 잠김':u.equipped.includes(id)?'장착 중':'장착',known?'learn':'equip',`data-id="${id}" data-runner="${u.id}" ${known&&!gate.ok?'disabled':''}`,u.equipped.includes(id)?'small active':'small'):''}</div>`};
const inheritedNormals=new Set((u.inheritanceHistory||[]).flatMap(h=>h.acquired||[]).map(E.canonicalSkillId));
const whiteUpgrades=available.filter(id=>E.skills.get(id)?.rarity===2&&[...E.ancestors(id)].some(base=>inheritedNormals.has(base)&&u.learned.includes(base)));
const whiteIds=new Set(whiteUpgrades);
const rows=(ids,known)=>`<div class="runner-skill-grid">${skillRowsHTML31(ids,row,u,known)}</div>`;
const acquiredRow=(id,known)=>row(id,known)+(known?'':whiteUpgrades.filter(rare=>E.ancestors(rare).has(id)).map(rare=>`<div class="skill-linked31 white-upgrade"><small class="skill-link-label31">백인자 · 레어 강화</small>${row(rare,true)}</div>`).join(''));
return `<div class="note strong-note">내장기는 처음부터 해방됩니다. 레어 스킬은 하위 노말 습득 후 강화합니다. 강화하면 기존 하위 스킬을 대체하며 같은 트리의 하위·상위 스킬은 동시에 장착할 수 없습니다. 원본에 하위 노말이 없는 독립 레어는 바로 습득합니다.</div><h3 class="subheading">획득 스킬 · 장착 ${u.equipped.length}/8</h3>${u.learned.length?`<div class="runner-skill-grid">${skillRowsHTML31(u.learned,acquiredRow,u,false)}</div>`:empty('해금 목록에서 스킬을 습득하세요.')}<h3 class="subheading">해금된 스킬 · 내장된 스킬</h3><p class="note">의상 내장 스킬과 하위 노말입니다. 장착 서포트의 해금 스킬과 겹치면 이 목록에서 30% 할인을 적용합니다.</p>${available.some(i=>!whiteIds.has(i)&&E.skillOrigin(u,i).innate)?rows(available.filter(i=>!whiteIds.has(i)&&E.skillOrigin(u,i).innate),true):empty('미습득 내장 스킬이 없습니다.')}<h3 class="subheading">해금된 스킬 · 서포트 카드로 해금된 스킬</h3><p class="note">장착 서포트의 스킬과 연결된 상위 스킬입니다. SSR 30% · SR 20% · R 10% 중 가장 높은 할인을 적용합니다.</p>${available.some(i=>!whiteIds.has(i)&&!E.skillOrigin(u,i).innate)?rows(available.filter(i=>!whiteIds.has(i)&&!E.skillOrigin(u,i).innate),true):empty('서포트로 해금된 미습득 스킬이 없습니다.')}<h3 class="subheading">백인자로 해금된 스킬 · 레어 강화</h3><p class="note">백인자로 습득한 일반 스킬에서 강화할 수 있는 레어 스킬입니다.</p>${whiteUpgrades.length?rows(whiteUpgrades,true):empty('백인자로 해금된 레어 스킬이 없습니다.')}<h3 class="subheading">내장 레어 → 진화</h3><p class="note">원본 레어 습득 후 진화 기회 1회 사용 · GⅠ 우승마다 기회 +1. 남은 기회 ${E.evolutionChances(u)}회 (통산 GⅠ ${u.g1wins}승 / 사용 ${u.evolved.length}회) · 한 원본 레어에서 한 분기 선택</p>${o.evolutionSkills.map(ev=>`<div class="evolution-row"><div>${skillButton(ev.old)}<span>→</span>${skillButton(ev.new)}</div>${u.evolved.includes(ev.new)?chip('진화 완료'):owned?button('진화','evolve',`data-id="${ev.new}" data-runner="${u.id}" ${E.evolutionChances(u)<1||!u.learned.includes(ev.old)?'disabled':''}`,'small'):''}</div>`).join('')}<h3 class="subheading">계승 고유기 · 획득 ${u.inheritLearned.length}/6 · 장착 ${u.inheritEquipped.length}/3</h3>${u.inheritLearned.map(id=>`<div class="skill-row">${skillButton(id)}${owned?button(u.inheritEquipped.includes(id)?'장착 중':'장착','inheritEquip',`data-id="${id}" data-runner="${u.id}"`,'small'):''}</div>`).join('')}${u.inheritKnown.map(x=>`<div class="skill-row">${skillButton(x.id)}<small>${x.cost} Pt</small>${owned?button('계승기 습득','inheritLearn',`data-id="${x.id}" data-runner="${u.id}"`,'small'):''}</div>`).join('')}`}
function factorCard(f,runner=null){const o=E.outfits.get(f.outfit);return `<article class="factor-card"><div class="factor-title">${image(o,'avatar')}<div><h3>${esc(f.name)}</h3><small>${esc(o.ko)}</small></div>${chip(f.rental?(f.used?'반환됨':f.ownedRental?'대여 중':'1회 대여'):'영구 인자')}</div><div class="factor-colors"><span class="blue-factor">청 ${statNames[f.blue.stat]} ${'★'.repeat(f.blue.stars)} · +${[0,3,6,10][f.blue.stars]}</span><span class="red-factor">적 ${aptNames[f.red.apt]} ${'★'.repeat(f.red.stars)} · ${[0,20,40,60][f.red.stars]}%</span><span class="green-factor">녹 고유기 · 등급 없음 · 150 Pt</span></div><div class="skill-pills">${f.green.skill?skillButton(f.green.skill):'계승기 없음'}</div><small>백인자 ${f.white.length}/6 · 각 50% 즉시 습득</small><div class="skill-pills">${f.white.map(i=>skillButton(i)).join('')}</div>${runner?button('인자 계승','applyFactor',`data-id="${f.id}" data-runner="${runner.id}" ${f.used?'disabled':''}`,'primary full'):''}</article>`}
function runnerFactors(u,owned){const period=E.factorWindow(S,u),fs=E.ownedFactors(S);return `<div class="note strong-note">주니어·클래식·시니어 1년차에 각 1회 · 해당 기간 내 언제든 사용${period?'<br>현재 계승 가능':'<br>현재 계승 불가'}</div><p class="note">청인자 +3/+6/+10 · 적인자 1성 +1 40% · 2성 +1 60% · 3성 +1 50% / +2 25% (나머지는 변화 없음, 최대 S) · 녹인자 계승기 150 Pt · 백인자는 각 50%로 즉시 습득합니다. 같은 트리 상위 스킬을 이미 습득했다면 하위 스킬을 중복 획득하지 않습니다.</p>${[['대여한 인자',fs.filter(f=>f.rental)],['고유 인자',fs.filter(f=>!f.rental)]].map(([label,rows])=>`<h3 class="subheading">${label} · ${rows.length}개</h3><p class="note">${label==='대여한 인자'?'시작·스카우트 대여 인자 · 1회 계승 후 반환되어 목록에서 사라집니다.':'직접 은퇴시켜 얻은 영구 인자 · 다른 우마무스메에게 재사용 가능합니다.'}</p><div class="factor-grid compact-factor-grid">${rows.map(f=>factorCard(f,owned?u:null,true)).join('')||empty('보유 인자 없음')}</div>`).join('')}`+inheritanceHistoryHTML(u)}
function recordTable(h){return h.length?`<div class="table-wrap"><table><thead><tr><th>일정</th><th>레이스</th><th>성적</th><th>포인트</th></tr></thead><tbody>${h.map(h=>`<tr><td>${date(h.at%24,Math.floor(h.at/24)+1)}</td><td>${(()=>{const result=S.results.find(r=>r.at===h.at&&r.race.key===h.key);return result?button(esc(h.race),'result','data-id="'+result.id+'"','text'):esc(h.race)})()}</td><td><b class="${h.pos===1?'gold-text':''}">${h.pos}위</b></td><td>+${h.points}</td></tr>`).join('')}</tbody></table></div>`:empty('첫 레이스의 기록을 기다리고 있습니다.')}
function racesPage(){const t=raceTurn??S.turn;const own=E.own(S),at=(S.year-1)*24+t+(t<S.turn?24:0),all=E.racesAt(S,t),races=raceAll?all:all.filter(r=>own.some(u=>E.projectRace(S,u,r,at).ok));return `<div class="calendar-strip">${Array.from({length:12},(_,m)=>`<button class="${Math.floor(t/2)===m?'active':''}" data-action="raceMonth" data-month="${m}"><small>${m+1}월</small><span>${m===Math.floor(S.turn/2)?'CURRENT':'RACE'}</span></button>`).join('')}</div><div class="section-label"><div class="tabs">${button('전반','raceHalf','data-half="0"',t%2===0?'active':'')}${button('후반','raceHalf','data-half="1"',t%2===1?'active':'')}</div><span class="muted">${t===S.turn?'이번 턴 활동에서 즉시 출전 가능':'미래 출전 예약 가능 · 지난 달 선택 시 다음 해'}</span></div>${button(raceAll?'전체 경주 표시 중':'조건·적성 통과 경주만','raceFilter','','small')}${reservationsHTML()}${panel((Math.floor(t/2)+1)+'월 '+(t%2?'후반':'전반')+' 레이스',raceTable(races))}${panel('출전 계획',own.map(u=>`<div class="line-item">${runnerHead(u)}<div><b>${u.entry?esc(races.find(r=>r.key===u.entry)?.name||'출전 등록됨'):'출전 미등록'}</b><small>${styleNames[u.style]} · 컨디션 ${E.conditionName(u)}</small></div>${u.entry?button('등록 취소','cancelEntry','data-id="'+u.id+'"','small'):''}</div>`).join(''))}`}
function openRace(key,t=S.turn){const r=E.racesAt(S,Number(t)).find(r=>r.key===key);if(!r)return;const at=(S.year-1)*24+Number(t)+(Number(t)<S.turn?24:0),current=at===E.abs(S),field=current?E.raceField(S,r):[];if(current)persist();showModal(`<span class="eyebrow">RACE ENTRY · ${current?'이번 턴':(2027+Math.floor(at/24))+'년 예약'}</span><h2 class="modal-title">${esc(r.name)}</h2><div class="race-facts">${[['등급',E.gradeName(r)],['일정',date(Number(t))],['경기장',r.track],['주로',r.terrain===2?'더트':'잔디'],['거리',r.distance+'m · '+aptNames[E.distType(r)+2]],['방향',direction(r)],['계절',['','봄','여름','가을','겨울','봄'][r.season]],['시간대',['','아침','낮','저녁','야간'][r.time]],['정원',r.entries+'명'],['우승 상금',money(E.price(r))]].map(([k,v])=>`<div><small>${k}</small><b>${esc(v)}</b></div>`).join('')}</div><p class="note">GⅠ은 모브 없이 실제 등록 우마무스메로 편성됩니다. 전체 목장 소속 우마무스메가 출전합니다. 각 목장 현역·미데뷔는 최대 4명입니다. GⅡ 65%, GⅢ 40%, 그 아래 20%를 목표로 하며 신마전은 각 우마무스메와 모브 상대만으로 개별 진행합니다. 동일 개체의 레이스·성장·활동·랭킹 기록이 연동됩니다. 상대는 경기장·거리·각질 적성 B 이상만 출전합니다. 모브의 주로와 선호 거리는 GameTora 출전 데이터를 따르며 능력치는 FM 난이도로 생성합니다.</p><h3 class="subheading">소속 우마무스메 · 적성 대조</h3>${E.own(S).map(u=>{const q=E.projectRace(S,u,r,at),warnings=E.aptWarnings(u,r),p=field.find(x=>x.id===u.id)?.popularity;return `<div class="entry-card ${!q.ok?'race-entry-blocked':''}"><div class="entry-row">${runnerHead(u)}<div><small class="${!q.ok?'race-entry-reason':''}">${esc(q.why)}</small><select class="race-style" id="style-${u.id}" data-runner="${u.id}" data-race="${esc(key)}">${styleNames.map((n,i)=>`<option value="${i}" ${u.style===i?'selected':''}>${n} · 적성 ${UmaFM.apt(u.apt[i+6])}</option>`).join('')}</select></div>${current?button(u.entry===key?'등록됨 · 인기 '+p+'번':'출전 등록','enter',`data-id="${u.id}" data-key="${esc(key)}" ${!q.ok||S.pendingTurn?'disabled':''}`,'primary small'):button('출전 예약 ('+(u.reservations||[]).length+'/4)','reserve',`data-id="${u.id}" data-key="${esc(key)}" data-at="${at}" ${!q.ok||(u.reservations||[]).length>=4||S.pendingTurn?'disabled':''}`,'primary small')}</div><div class="apt-match">${[E.groundIndex(r),E.distType(r)+2,u.style+6].map(i=>chip(aptNames[i]+' '+UmaFM.apt(u.apt[i]),u.apt[i]<=4?'danger':'')).join('')}<span id="apt-warning-${u.id}" class="${warnings.length?'apt-warning':'muted'}">${warnings.length?'⚠ 적성 부적합(C 이하): '+warnings.join(' · '):'경기장·거리·각질 적성 적합'}</span></div>${statGrid(u)}${raceReadinessHTML(u,r)}<p class="${E.raceLoad(S,u).consecutive?'apt-warning':'note'}">과밀 출전 상태이상 위험 ${(E.raceLoad(S,u).risk*100).toFixed(1)}% · 최근 6턴 ${E.raceLoad(S,u).recent}회 출전${E.raceLoad(S,u).consecutive?' · 두 턴 연속 출전 주의':''}</p></div>`}).join('')}<h3 class="subheading">출전 명단 · 인기와 능력치</h3>${r.grade===900?'<p class="note">신마전은 우마무스메 한 명씩 개별 진행합니다. 모든 상대는 모브이며 소속 동료·라이벌과 같은 조에 배치되지 않습니다.</p>':''}${current?fieldTable(field,r):'<p class="note">해당 턴에 출전 명단이 확정됩니다.</p>'}<p class="note">인기는 능력치·코스 적성을 바탕으로 한 예상 순위이며 승리를 보장하지 않습니다. 경기장 날짜는 고정이며 경주 판단은 독립 난수로 계산합니다.</p>`)}
function resultsPanel(){const rr=S.results.filter(r=>r.rows.some(x=>x.team===0)).slice(0,15);return panel('목장 레이스 결과',rr.map(r=>`<button class="result-preview" data-action="result" data-id="${r.id}"><span class="race-grade grade-${r.race.grade}">${E.gradeName(r.race)}</span><div><b>${esc(r.race.name)}</b><small>${date(r.at%24,Math.floor(r.at/24)+1)} · ${r.rows.filter(x=>x.team===0).map(x=>esc(x.name||E.outfits.get(x.outfit).characterKo)+' '+x.pos+'위').join(' · ')}</small></div><em>결과 ↗</em></button>`).join('')||empty('아직 출전 결과가 없습니다.'))}
function rankingPage(){const rows=E.ranking(S,rankStage,rankDisc),labels={junior:'주니어',classic:'클래식',senior:'시니어'};return `<div class="tabs page-tabs">${Object.entries(labels).map(([k,n])=>button(n,'rankStage',`data-key="${k}"`,rankStage===k?'active':'')).join('')}</div><div class="tabs page-tabs">${Object.entries(E.disciplines).map(([k,n])=>button(n,'rankDisc',`data-key="${k}"`,rankDisc===k?'active':'')).join('')}</div>${panel(labels[rankStage]+' · '+E.disciplines[rankDisc]+' 랭킹',`<p class="note">현재 해당 세대에 소속된 현역의 ${E.calendarYear(S)}년 성적을 실시간 평가합니다. GⅠ 1착 경기평가 100, 2착 40. 매 경기 평가를 합산하고, 상위 40% 밖의 착순은 낮을수록 큰 음수 평가를 받습니다. 매년 1월 기록이 새로 시작되며 이전 기록은 개인 기록실에 남습니다. 거리 부문은 잔디 단거리·마일·중거리·장거리와 더트로 구분합니다. 1월에는 새 주니어 세대가 6월 데뷔를 준비합니다.</p><div class="cohort-summary">AI 세대 정원 · 주니어 ${E.leaguePlan.targets[1]}명 / 클래식 ${E.leaguePlan.targets[2]}명 / 시니어 ${E.leaguePlan.targets[3]}명 (1년차100 · 2년차50 · 3년차33 · 4년차17) · 적성·휴식·출전 자격에 따라 독립 활동</div><div class="ranking-table">${rows.map(({runner:u,record:r},i)=>`<article class="world-rank ${u.team===0?'mine':''}"><b class="rank-number">${i+1}</b><button class="rank-profile" data-action="runner" data-id="${u.id}">${runnerHead(u)}<small>${esc(S.teams[u.team]?.name)} · ${u.released?'방출':E.ageName(S,u)}</small></button><div class="rank-record"><strong>${r.points} PT</strong><span>${r.starts}전 ${r.wins}승 · GⅠ ${r.g1}승</span><small>${r.titles.map(t=>esc(t.race||t)).join(' · ')||'주요 우승 없음'}</small><div class="recent-five">${r.recent.map((h,k)=>button(h.pos+'착','rankRecord',`data-runner="${u.id}" data-index="${k}"`,'small '+(h.pos===1?'winner':''))).join('')||'<span>해당 기간 출전 없음</span>'}</div></div></article>`).join('')}</div>${rows.length?'':empty('6월 신마전 이후 주니어 랭킹이 시작됩니다.')}`)}${panel('JRA 연말 시상',`<p>매년 12월 후반 종료 시 당해 성적만으로 각 부문과 현창 우마무스메를 선정합니다. 수상 내역은 개인·목장 기록실에 남습니다. 12월 후반 종료 후 시상하며, 당해 직접 은퇴한 명마는 현창 우마무스메 심사 대상입니다.</p>${button('연도별 수상 기록','nav','data-view="hall"','small')}`)}`}
function supportsPage(){const cards=DB.supports.filter(c=>S.supports[c.gameId]>0&&(supportFilter==='all'||c.rarity===supportFilter));return `<section class="gacha-banner"><div><span class="eyebrow">PERMANENT SUPPORT</span><h2>여섯 장으로 함께 만드는 성장.</h2><p>매 턴 뽑기권 1장 · GⅠ 1~3착 +3/+2/+1장 · GⅡ 1~3착 +2/+1/+1장 · GⅢ 우승 +1장 · 최초 10장<br>주니어 3장 · 클래식 추가 3장 · 전체 6장</p></div><div>${button('1회 뽑기 · 티켓 1장','draw','data-count="1"','primary')}${button('10회 뽑기 · 티켓 10장','draw','data-count="10"','lime')}</div></section><div class="section-label"><h2>미장착 보유 카드 <small>${cards.length}종</small></h2><div class="tabs">${['all','SSR','SR','R'].map(f=>button(f==='all'?'전체':f,'supportFilter','data-filter="'+f+'"',supportFilter===f?'active':'')).join('')}</div></div><div class="support-grid">${cards.map(c=>`<article class="support-card"><button class="support-image" data-action="support" data-id="${c.gameId}">${image(c)}<span class="rarity-tag ${c.rarity}">${c.rarity}</span><span class="inventory-support-type">${supportTypeBadge(c)}</span><span class="copy-count">×${S.supports[c.gameId]}</span></button><small>${esc(c.koCharacter)}</small><h3>${esc(c.ko)}</h3>${supportRareHTML(c,false)}${button('장착 · 스킬 보기','support','data-id="'+c.gameId+'"','small full')}</article>`).join('')}</div>${cards.length?'':empty('뽑기권으로 새 서포트를 확보하세요.')}`}
function openSupport(id){const c=DB.supports.find(c=>c.gameId===Number(id));if(!c)return;const k=UmaFM.TYPES[c.type],bonus='훈련 출현 '+Math.round(E.supportAppearance(c)*100)+'% · 일반 +1 · 속성 우정 +3 · 친구·그룹 우정 +2 노력치 · 특기 배치 40%';showModal(`<div class="support-detail"><div>${image(c,'large-card')}</div><section><span class="eyebrow">PERMANENT SUPPORT · ${c.rarity}</span><h2>${esc(c.ko)}</h2><p>${esc(c.koCharacter)} · 미장착 보유 ${S.supports[c.gameId]||0}장</p><div class="note strong-note">${bonus}<br>장착 후 해제 불가 · 스킬 목록이 내장되어 Pt로 획득 가능<br>동일 카드 ID는 한 우마무스메당 1장만 장착 가능 · 같은 캐릭터의 다른 카드는 장착 가능</div><label>장착할 우마무스메<select id="supportRunner">${E.own(S).map(u=>{const sl=E.supportSlots(S,u);return `<option value="${u.id}">${esc(name(u))} · ${u.released?'방출':E.ageName(S,u)} · ${sl.used}/${sl.limit} (${sl.total}/6)${E.hasSupportCard(u,c.gameId)?' · 동일 카드 장착됨':''}</option>`}).join('')}</select></label>${button('영구 장착','useSupport',`data-id="${c.gameId}" ${!S.supports[c.gameId]?'disabled':''}`,'primary full')}<p id="supportEquipReason26" class="note" role="status"></p>${supportRareHTML(c)}<h3 class="subheading">제공 스킬과 하위 일반</h3><div class="skill-pills">${skillPillsHTML31(c.skills)}</div></section></div>`);updateSupportEquip26()}
function factorsPage(){const fs=E.ownedFactors(S);return `<p class="note">보유 인자 <b>${fs.length} / 20</b> · 백인자 각 50% 즉시 습득 · 우마무스메 상세에서 계승할 수 있습니다.</p>${[['대여한 인자',fs.filter(f=>f.rental)],['고유 인자',fs.filter(f=>!f.rental)]].map(([title,rows])=>panel(title+' · '+rows.length,`<p>${title==='대여한 인자'?'시작·스카우트에서 확보한 1회 대여 인자. 사용 후 반환됩니다.':'직접 은퇴로 얻은 영구 인자입니다.'}</p><div class="factor-grid compact-factor-grid">${rows.map(f=>factorCard(f,null,true)).join('')||empty('보유 인자 없음')}</div>`)).join('')}`}
function scoutPage(settings=''){return `<div class="tabs page-tabs">${[['uma','미데뷔 스카우트'],['support','서포트 경매'],['factor','인자 경매 · 1회 대여']].map(([v,n])=>button(n,'scoutTab','data-tab="'+v+'"',scoutTab===v?'active':'')).join('')}</div>${settings}<p class="note">우마무스메는 확정 계약, 서포트와 1회 대여 인자는 확률 경매입니다. 매달 전반에 상품이 갱신됩니다.</p>${scoutTab==='uma'?`<div class="section-label"><h2>미데뷔 후보 보고서</h2>${button('추가 탐색 · ₩30,000','refreshScout','','small')}</div><p class="note">별 등급만으로 계약금을 정합니다. 1★ ₩18,000 / 2★ ₩35,000 / 3★ ₩70,000 / 4★ ₩150,000 / 5★ ₩350,000</p><div class="scout-odds">${E.scoutOdds.map((n,i)=>`<span><b>${i+1}★</b> ${n}%</span>`).join('')}</div><p class="note">성급 출현 확률은 스카우트 레벨과 관계없이 고정입니다. Lv.1 후보 3명, 레벨마다 2명 추가 (Lv.5 11명).</p><div class="scout-grid">${S.scouts.map(c=>{const o=E.outfits.get(c.outfit);return `<article class="scout-card ${c.stars===5?'scout-five-star':''}"><div class="scout-art">${image(o,'',true)}</div><div class="scout-body"><small>${esc(o.ko)}</small><h3>${esc(o.characterKo)}</h3>${scoutAlertSettings().watch.includes(o.gameId)?'<span class="scout-watch-badge">★ 관심 의상</span>':''}<b class="gold-text">개체값 ${'★'.repeat(c.stars)}</b><div class="apt-summary">${o.aptitudes.map((a,i)=>a==='A'?chip(aptNames[i]+' A'):'').join('')}</div>${outfitEvolutionHTML(o,true)}<div class="scout-price"><strong>${money(c.cost)}</strong><small>소속 ${E.rosterCount(S)}/10</small></div>${button('적성 · 스킬 상세','outfitPreview','data-id="'+o.gameId+'"','small full')}${button('스카우트 계약','sign',`data-id="${c.id}" ${E.rosterCount(S)>=10?'disabled':''}`,'primary full')}</div></article>`}).join('')}</div>`:scoutTab==='support'?`<div class="note strong-note">R +₩500 / SR +₩1,000 / SSR +₩2,000씩 입찰합니다. 추가 입찰마다 표시 낙찰 확률이 상승하며 다음 턴 확정합니다. 유찰 시 예치금 전액 반환.</div><div class="support-grid support-auction-grid">${S.supportMarket.map(a=>{const c=E.supports.get(a.card),next=(a.bid||a.price)+E.auctionStep(a);return `<article class="support-card"><div class="market-support-art">${image(c)}${supportTypeBadge(c)}</div><h3>${esc(c.koCharacter)}</h3><p>${c.rarity} · ${esc(c.ko)}</p>${supportRareHTML(c,false)}${button('카드 스킬','support','data-id="'+c.gameId+'"','small full')}<p>현재 ${money(a.bid||a.price)}<br>${a.bid?'내 입찰 낙찰 확률 '+(E.auctionChance(a)*100).toFixed(1)+'%':'입찰 전'}<br>다음 입찰 ${money(next)} · <b>${(E.auctionChance(a,next)*100).toFixed(1)}%</b></p>${button(a.sold?(a.status==='won'?'낙찰 완료':a.status==='lost'?'유찰 · 반환 완료':'종료'):'+'+money(E.auctionStep(a))+' 입찰','bidSupport',`data-id="${a.id}" ${a.sold?'disabled':''}`,'primary full')}</article>`}).join('')}</div>${(S.auctionResults||[]).length?panel('최근 낙찰 결과',S.auctionResults.slice(0,5).map(a=>`<div class="line-item">${esc(E.supports.get(a.card).koCharacter)} · ${a.won?'낙찰':'유찰·반환'}<b>${money(a.bid)} · 확률 ${(a.chance*100).toFixed(1)}%</b></div>`).join('')):''}`:`<div class="note strong-note">인자 경매 · 1회 대여<br>추가 입찰마다 낙찰 확률이 상승하며 다음 턴 확정합니다. 유찰 시 전액 반환. 낙찰 인자는 계승 직후 반환되어 목록에서 사라집니다.</div><p class="note">스카우트 레벨이 높을수록 청·적 3성과 많은 백인자 조합의 출현 확률이 증가합니다. 청3·적3·백6은 Lv.5에서 1%입니다.</p><div class="factor-grid factor-auction-grid">${S.factorMarket.map(a=>{const f=S.factors.find(f=>f.id===a.factor),next=(a.bid||a.price)+E.auctionStep(a);return `<section>${f?factorCard(f):'<div class="empty">반환된 대여 인자</div>'}<div class="auction-summary">기준가 ${money(a.price)}<br>현재 ${money(a.bid||a.price)}${a.bid?'<br>내 입찰 낙찰 확률 '+(E.auctionChance(a)*100).toFixed(1)+'%':''}<br>다음 입찰 ${money(next)} · <b>${(E.auctionChance(a,next)*100).toFixed(1)}%</b></div>${button(a.sold?(a.status==='won'?'낙찰 · 1회 대여':a.status==='lost'?'유찰 · 반환 완료':'종료'):'+'+money(E.auctionStep(a))+' 입찰','bidFactor',`data-id="${a.id}" ${a.sold?'disabled':''}`,'primary full')}</section>`}).join('')}</div>${(S.factorAuctionResults||[]).length?panel('인자 경매 결과',S.factorAuctionResults.slice(0,5).map(a=>`<div class="line-item">${esc(a.name)} · ${a.won?'낙찰 · 1회 대여':'유찰 · 전액 반환'}<b>${money(a.bid)} · ${(a.chance*100).toFixed(1)}%</b></div>`).join('')):''}`}`}
function medicalPage(){return `${panel('메디컬 센터',`<p>연속 두 턴 출전, 최근 6턴의 잦은 출전, 낮은 컨디션과 피로는 부상 확률을 높입니다. AI도 같은 부하 규칙을 적용받으며 연속 출전은 피합니다. 부상은 치료를 시작해야 회복됩니다. 필요한 치료비는 자금 부족 시 차입으로 처리됩니다.</p><p class="note">다리 부상·염좌·골절·입스 · 치료 기간 중 출전 및 훈련 불가 · 완치 턴에는 안정 휴식</p>`)}<div class="runner-grid full">${E.own(S).map(u=>{const m=u.medical,load=E.raceLoad(S,u);return `<article class="runner-card">${runnerHead(u)}<div class="health-grid"><span>컨디션<b>${E.conditionName(u)}</b></span><span>체력<b>${u.energy??100}</b></span><span>상태<b>${m?esc(m.name):u.injury?'치료 필요':'정상'}</b></span></div>${m?`<div class="medical-course"><b>${m.treating?'치료 중':'미치료'} · 남은 ${m.remaining}턴</b><progress max="${m.total}" value="${m.total-m.remaining}"></progress><p>${m.treating?'매 턴 치료 경과가 반영됩니다.':money(m.fee)+' · 치료를 시작해야 회복됩니다.'}</p>${m.treating?'':button('치료 시작','startTreatment','data-id="'+u.id+'"','primary')}</div>`:`<p class="note">현재 예상 경주 부상 위험 ${(load.risk*100).toFixed(1)}% · 최근 6턴 ${load.recent}회 출전${load.consecutive?' · 연속 출전 주의':''}</p><div class="row-actions">${button('휴식 고정','rest','data-id="'+u.id+'"','small')}${button('자동 훈련 재개','autoTrain','data-id="'+u.id+'"','small')}${button('컨디션 케어 · ₩1,800','treat','data-id="'+u.id+'"','small primary')}</div>`}<p class="note">최근 치료: ${(u.medicalHistory||[]).slice(0,3).map(h=>esc(h.name)+' 완치').join(' · ')||'없음'}</p></article>`}).join('')}</div>`}
function financePage(){const costs=E.upkeepBreakdown(S),monthly=E.fanMonthly(S);return `${financeChartHTML()}${cashflowHTML(E.turnCashflow(S),!!S.pendingTurn)}<div class="finance-summary"><article><small>운영 자금</small><h2>${money(S.funds)}</h2></article><article><small>월 예상 팬 수익</small><h2>${money(monthly)}</h2></article><article><small>월 고정 지출</small><h2>${money(costs.total)}</h2></article></div>${panel('매달 후반 · 생활비 정산',`<p>미데뷔 1명 월 ₩900 · 현역 1명 월 ₩2,100 · 기존 대비 40% 인하. 은퇴·방출 우마무스메는 제외합니다. 팬 수익과 월 고정 지출은 매달 후반 결산을 표시하기 전에 정산됩니다.</p><div class="table-wrap"><table><thead><tr><th>우마무스메</th><th>식비</th><th>생활비</th><th>개인 유지비</th><th>월 합계</th></tr></thead><tbody>${costs.items.map(c=>`<tr><td>${esc(c.name)} · ${c.status==='active'?'현역':'미데뷔'}</td><td>${money(c.food)}</td><td>${money(c.living)}</td><td>${money(c.care)}</td><td>${money(c.total)}</td></tr>`).join('')}</tbody></table></div><p>시설 유지비 ${money(costs.facilities)} · 예상 월 순수익 <b>${money(monthly-costs.total)}</b></p>`)}${panel('수익 구조',`<p>수입은 레이스 상금과 현역 팬 수익입니다. 현역 팬 1명당 월 ₩0.8, 팬 최대 50,000명. 성적 하락 시 이탈하며 시니어 3~4년차 신규 팬 증가는 거의 없습니다. 은퇴하면 팬 수익도 사라집니다.</p>${E.active(S).map(u=>`<div class="line-item">${runnerHead(u)}<b>${u.fans.toLocaleString()}명 · 월 ${money(Math.floor(u.fans*.8))}</b></div>`).join('')}`)}${panel('목장 장부',`<div class="table-wrap"><table><thead><tr><th>날짜</th><th>항목</th><th>금액</th></tr></thead><tbody>${S.ledger.slice(0,100).map(l=>`<tr><td>${date(l.at%24,Math.floor(l.at/24)+1)}</td><td>${esc(l.label)}</td><td>${money(l.amount)}</td></tr>`).join('')}</tbody></table></div>`)}`}
function facilitiesPage(){return `<div class="facility-grid">${[['training','훈련 시설','↗',`훈련 턴마다 미분배 노력치 ${S.fac.training+1} Pt 획득. 직접 분배하며 총합 200에서 종료.`],['medical','메디컬 센터','✚','휴식 회복 증가 · 부상 확률 감소'],['scout','스카우팅 센터','⌕','우마무스메 후보 레벨마다 +2명 (3→5→7→9→11) · 별 확률 고정 · 서포트·인자 상품 별도 확장']].map(([k,n,ic,desc])=>`<article class="facility-card"><span class="facility-icon">${ic}</span><h2>${n}</h2><div class="facility-level">Lv.${S.fac[k]}<small>/5</small></div><p>${desc}</p><small>월 유지비 ${money(S.fac[k]**2*180)}</small>${button(S.fac[k]>=5?'최고 단계':money(35000*S.fac[k]**2)+' 확장','upgrade',`data-key="${k}" ${S.fac[k]>=5?'disabled':''}`,'primary full')}</article>`).join('')}</div>`}
function hallPage(){return `${panel('목장 수상 기록',`<div class="award-grid">${(S.teams[0].awards||[]).map(a=>awardHTML(a)).join('')||empty('매년 12월 후반 JRA 수상에 도전하세요.')}</div>`)}${panel('기록실',`<div class="scout-grid">${S.hall.map(h=>`<article class="hall-card">${image(E.o(h.runner),'hall-art',true)}<div><h2>${esc(name(h.runner))}</h2><p>${h.runner.starts}전 ${h.runner.wins}승 · GⅠ ${h.runner.g1wins}승</p>${button('개인 기록 · 수상','runner','data-id="'+h.runner.id+'" data-tab="record"','small')}</div></article>`).join('')||empty('은퇴한 소속 우마무스메가 기록됩니다.')}</div>`)}${panel('JRA 연도별 시상식',`${(S.awards||[]).map(y=>`<h3 class="subheading">${y.year} JRA AWARDS</h3><div class="award-grid">${y.items.map(awardHTML).join('')}</div>`).join('')||empty('첫 연말 시상식을 기다리고 있습니다.')}`)}${panel('연말 결산',`${S.history.map(h=>`<div class="line-item"><b>${h.calendarYear||(h.year>2000?h.year:2026+h.year)}년</b><span>연말 자금 ${money(h.balance)}</span></div>`).join('')||'결산 전'}`)}`}
function dexPage(){return `<div class="section-label"><div class="tabs">${[['outfits','육성 의상'],['supports','서포트 카드'],['skills','스킬'],['courses','경기장'],['races','레이스'],['titles','타이틀']].map(([key,label])=>button(label,'dexTab',`data-tab="${key}"`,dexTab===key?'active':'')).join('')}</div><input class="search-input" id="dexSearch" value="${esc(search)}" placeholder="이름·거리·타이틀 검색" aria-label="도감 검색"></div>${dexFiltersHTML()}<div id="dexResults">${dexResultsHTML()}</div>`}
function showSkill(id){const s=E.skills.get(Number(id));if(!s)return;const family=s.treeFamily.map(i=>E.skills.get(i)).filter(Boolean);showModal(`<span class="eyebrow">SKILL DATABASE · JP</span><h2 class="modal-title skill-heading">${skillIcon(s)}${esc(s.name)}</h2><p class="muted">${esc(s.original)}${s.referenceName?' · 한국어 참고 번역':''}</p><div class="skill-description">${esc(s.desc)}</div><div class="tags">${chip(s.inheritedSkill?'계승':s.rarity===6?'진화':s.rarity===2?'레어':s.rarity>=3?'고유':'노멀')}${s.cost!=null?chip(s.cost+' Pt'):''}</div>${family.length?`<h3 class="subheading">스킬 트리</h3><div class="tree-family">${skillPillsHTML31(family.map(s=>s.id))}</div>`:''}${skillCategoryBadges(s.id)}${skillMechanicsHTML(s.id)}${skillOutfitSourcesHTML(s.id)}${skillSourcesHTML(s.id)}${S.startup&&starterPreview?button('후보 상세로 돌아가기','starterPreview','data-kind="'+starterPreview.kind+'" data-index="'+starterPreview.index+'"','primary'):''}<details class="source-details"><summary>일본어 효과 원문</summary><p>${esc(s.originalDesc||'원문 미등록')}</p></details><p class="note">조건에 맞는 장착 스킬이 실제 각질·주로·거리·순위 조건을 만족하면 발동합니다.</p>${selected?button('현역 상세로 돌아가기','runner','data-id="'+selected+'" data-tab="skills"','small'):''}`)}
function showReport(){const r=S.pendingTurn||S.lastReport;if(!r)return;const f=E.turnCashflow(S,r,!!S.pendingTurn);showModal(`<div class="turn-report-compact"><span class="eyebrow">TURN REPORT · ${S.pendingTurn?'결과 확인 후 다음 턴':'기록'}</span><h2 class="modal-title">${date(r.at%24,Math.floor(r.at/24)+1)} 결산</h2>${cashflowHTML(f,!!S.pendingTurn,true)}${auctionReportHTML(r)}${noviceReportHTML(r)}<div class="report-grid"><div><small>출전 경기</small><b>${r.races.length}</b></div><div><small>훈련한 현역</small><b>${r.growth.length}</b></div><div><small>현재 자금</small><b class="${S.funds<0?'red':''}">${money(S.funds)}</b></div></div>${r.races.map(id=>{const result=S.results.find(x=>x.id===id);return result?`<button class="result-preview" data-action="result" data-id="${id}"><b>${esc(result.race.name)}</b><span>${result.rows.filter(x=>x.team===0).map(x=>esc(x.name)+' '+x.pos+'위').join(' · ')}</span><em>전체 결과 ↗</em></button>${result.trace?button('경주 관전 · 1/2/3배속','watchNext','data-id="'+id+'"','small'):''}`:''}).join('')}${S.pendingTurn?button('결산 확인 완료 · 다음 턴으로 →','finishTurn','','primary full'):button('닫기','close','','primary full')}</div>`)}
function showResult(id,replay=false){if(replay){playRace(id,true);return}const result=S.results.find(r=>r.id===Number(id));if(!result)return;const r=result.race;showModal(`<span class="eyebrow">RACE ${replay?'REPLAY':'RESULT'} · ${date(result.at%24,Math.floor(result.at/24)+1)}</span><h2 class="modal-title">${esc(r.name)}</h2><p>${esc(r.track)} · ${r.terrain===2?'더트':'잔디'} ${r.distance}m · ${result.rows.length}명</p>${rewardReceiptHTML(result)}${raceRatingHTML(result)}${raceDiagnosticsHTML(result)}<div class="race-podium">${result.rows.slice(0,3).map(x=>`<article><b>${x.pos}</b><img src="${esc(x.image||E.outfits.get(x.outfit).image)}" alt=""><strong>${esc(x.name||E.outfits.get(x.outfit).characterKo)}</strong><small>${x.time?raceClock(x.time):'기존 기록'}</small></article>`).join('')}</div><div class="table-wrap race-result-table"><table><thead><tr><th>순위</th><th>출전자</th><th>각질</th><th>연차</th><th>인기</th>${statNames.map(n=>'<th>'+n+'</th>').join('')}<th>바로 뒤와 착차</th><th>잔여 지구력</th><th>사건·스킬</th></tr></thead><tbody>${result.rows.map((x,i)=>`<tr class="${x.team===0?'mine':''}"><td><b>${x.pos}</b></td><td><img class="tiny-avatar" src="${esc(x.image||E.outfits.get(x.outfit).image)}" alt="">${esc(x.name||E.outfits.get(x.outfit).characterKo)}${x.mob?chip('모브'):''}</td><td>${styleNames[x.style]||'—'}</td><td>${esc(x.snapshot?.ageName||'기존 기록')}</td><td>${x.popularity?x.popularity+'번':'—'}</td>${(x.stats||Array(5).fill('—')).map(n=>'<td>'+n+'</td>').join('')}<td title="${E.finishMargin(result,i).meters==null?'마지막 주자':E.finishMargin(result,i).meters.toFixed(3)+'m'}"><b>${esc(E.finishMargin(result,i).label)}</b></td><td>${x.energy??'—'}%</td><td><small>${(x.events||[]).map(esc).join(' · ')}</small><div class="skill-pills">${x.activated.map(i=>skillButton(i)).join('')}</div></td></tr>`).join('')}</tbody></table></div>${raceSkillChecksHTML(result)}${raceSkillTimeline(result)}${result.trace?button('1분 경주 다시보기','replay','data-id="'+result.id+'"','primary'):''}${S.pendingTurn?nextRaceButton(result.id):''}${S.pendingTurn?`${button('턴 결과로 돌아가기','report','','small')}${button('결과 확인 완료 · 다음 턴으로 →','finishTurn','','primary full')}`:''}<p class="note">저장된 출전 당시 능력치와 결과입니다. 결과를 다시 계산하지 않습니다.</p>`)}
function rules(){showModal(`<span class="eyebrow">RANCH HANDBOOK · V11</span><h2>목장 운영 가이드</h2><div class="rulebook"><h3>목장과 시간</h3><p>2027년 1월 전반 시작 · 매년 24턴. 미데뷔는 6월 전반 신마전 참가 시 주니어가 되고 다음 해 클래식, 이후 시니어 1~4년차입니다. 목장 정원 10명·현역 4명, 미데뷔 방출은 보상 없습니다. 신마전 상대는 모브뿐이며, 미승리전은 6월 후반~9월 전반 열립니다. 첫 승 전에는 신마·미승리전 외 모든 레이스가 제한되고, 9월 전반 종료까지 첫 승이 없는 주니어는 인자 없이 은퇴합니다. 두 레이스 상대 능력은 기존보다 10% 낮췄습니다. 시니어 1년차 종료 후 은퇴 가능, 시니어 4년차 종료 시 자동 은퇴합니다. 플레이어 시니어 2/3/4년차 실전 능력은 5/10/15% 감소합니다.</p><h3>능력과 노력치</h3><p>스피드·스태미나·파워·근성·지능은 1~100입니다. 개체값은 18~30 고정, 스타터는 전부24. 훈련하면 미분배 노력치 포인트를 얻고 직접 배분합니다. 총합200, 초기화권은 ₩24,000. 컨디션50 미만이면85까지 휴식 후 훈련을 재개합니다. 개체값 18~21 보통이다 /22~25 좋다 /26~30 아주 좋다.</p><h3>스킬 트리와 서포트</h3><p>내장기는 처음부터 해방됩니다. 레어는 바로 아래 노말을 습득한 뒤 Pt로 강화하며 기존 하위 스킬을 대체합니다. 같은 트리의 하위·상위 스킬 동시 장착은 불가합니다. 진화 조건은 원본 레어 습득과 진화 기회1회 사용 (GⅠ 우승마다1회 적립)으로 통일합니다. 일반·내장·진화 합계8개, 계승 고유기는 별도3개 장착(6개 획득)입니다. 내장 스킬과 그 하위 스킬은 원가 Pt를 사용하되, 장착 서포트의 해금 스킬과 겹치면 내장 칸에서 30% 할인합니다. 서포트 해방 스킬은 SSR 30%, SR 20%, R 10% 할인하며 가장 높은 할인 하나를 적용하고 소수점은 올립니다. 서포트는 미데뷔·클래식·시니어1년차에 각2장 영구 장착합니다. 속성 보너스 SSR/SR/R +15/8/5, 친구·그룹 전 능력 +5/2/1.</p><h3>대여 인자와 고유 인자</h3><p>시작 인자5개 중1개 선택: 청·적2성, 백3개 고정. 시작 인자와 스카우트 구매 인자는 모두1회 대여이며 계승 후 반환되어 목록에서 사라집니다. 직접 은퇴시켜 얻은 고유 인자만 영구 소유합니다. 인자 경매 기준가는 이전 버전의 6배이며 1회 대여 가치에 따라 책정합니다. 청 +3/6/10, 적인자 1성 +1 40%, 2성 +1 60%, 3성 +1 50% / +2 25%, 녹인자 계승기150 Pt, 백인자는 각각50%로 즉시 습득하여 Pt 없이 장착 가능합니다. 계승은 주니어·클래식·시니어1년차 각1회, 기간 내 언제든 가능합니다. 스카우트 레벨이 높을수록 좋은 청·적·백 조합 출현 확률이 증가하며 청3·적3·백6은 Lv.5에서1%입니다.</p><h3>스카우트·경매·무료 합성</h3><p>우마무스메는 별만으로 가격을 정합니다: 1★18,000 /2★35,000 /3★70,000 /4★150,000 /5★350,000. 별 출현 확률은 1~5성 순서로 45/30/15/7/3%로 고정이며, 시설 레벨마다 우마무스메 후보가 2명씩 늘어납니다. 우마무스메는 확정 구매, 인자·서포트는 경매합니다. 우마무스메 추가 탐색만 30,000원이며 서포트·인자 경매와 레이스는 리롤하지 않습니다. 서포트는 R500 /SR1,000 /SSR2,000씩 추가 입찰합니다. 화면에 표시된 낙찰 확률로 다음 턴 확정하며 유찰은 전액 반환합니다. R3→SR65%, SR3→SSR45%, SSR2→SSR1 확정. 합성 비용은 없습니다.</p><h3>뽑기권·생활비·메디컬</h3><p>처음10장, 매 턴 종료1장, GⅠ 1~3착 3/2/1장, GⅡ 1~3착 2/1/1장, GⅢ 1착 1장. 기존 미션은 삭제했습니다. 월 생활비40% 인하: 미데뷔900 /현역2,100. 시설 유지비는 별도입니다. 수입은 상금과 현역 팬 월 수익입니다. 연속 출전·최근 잦은 경주는 부상 위험을 높입니다. 다리 부상·염좌·골절·입스는 메디컬 치료를 시작해야 회복됩니다.</p><h3>현금 흐름과 채무</h3><p>결산을 열기 전에 경매와 월 후반 팬 수익·유지비를 확정하고 장부의 수입과 지출을 모두 합산합니다. 유찰 예치금 반환은 수입, 입찰 예치금은 지출로 표시하며 낙찰 때 중복 차감하지 않습니다. 생활·시설비 정산으로 자금이 음수가 되면 채무로 표시하고 상환 전 유료 구매·입찰·서비스를 제한합니다. 상금과 팬 수익은 자동으로 잔액을 회복합니다. 필수 월 비용과 기존 채무 월1% 이자는 계속 정산됩니다.</p><h3>경주 계산</h3><p><a href="https://dbzorim.github.io/race-simulator/#/champions-meeting" target="_blank" rel="noopener">참고 레이스 시뮬레이터</a>의 공개 코드에서 속도·가속·지구력·근성·스퍼트·각질/적성 계수와 발동률을 대조했습니다. FM 수치1~100을 계산용12~1200으로 환산하고 초당15프레임으로 계산합니다. 스태미나는 최대 지구력, 파워는 가속, 근성은 종반 속도와 소모, 지능은 발동률·구간 변동·내리막 판정에 관여합니다. 초반 위치 유지는 도주의 페이스업과 비도주 각질의 페이스다운을 적용합니다. 마군 막힘은 실제 앞뒤 거리와 횡방향 진로로 판정하고, 진로가 열려야 추월합니다. 바깥 코너는 추가 이동 거리가 생깁니다. 초반 도주 경합과 최종 직선 접전은 근성·HP·상대 위치·지속 조건에 따라 발생하고 종료됩니다. 원본 조건과 효과를 갖는 일본 서버 스킬 및 코스 구간을 연결합니다. 단일 코스 관전의 원형 인물 표시는 실시간 순위이며 게이트·인기 번호를 쓰지 않습니다. 겹침을 피하도록 표시 위치를 조금 벌립니다. 기본 관전60초를 기준으로 0.25~3배속, 되감기·1초 이동·구간 이동·시간축 그래프를 지원합니다. 관전 결과 난수는 바뀌지 않습니다. 착차는 바로 뒤 주자와 비교합니다.</p><p>이전 난이도에서 상대 실전 능력을 전체 10%, 추가로 주니어·클래식 20%, 시니어 7% 상향했습니다. 100 상한을 적용합니다. 상대 연차 노쇠는 별도로 적용됩니다. 클래식 전용전의 모브는 시니어전보다 낮은 능력으로 생성합니다. 라이벌은 경기 등급에 따라 임시 생성·강화하지 않고 목장에서 성장한 동일 개체가 출전합니다. 모브 능력치 예산은 라이벌보다 낮게 조정했습니다. 출전 전 전원 능력·적성·각질·연차·인기를 확인할 수 있습니다.</p><h3>라이벌·랭킹·뉴스</h3><p>랭킹 목장은 24곳이며 목장당 4명까지 운영합니다. 정규 경주 정원 유지를 위해 목장 외 JRA 등록 우마무스메도 독립적으로 활동합니다. 3턴 내 GⅠ 출전 자리 수68/75/81명에 휴식·부상25% 여유와 진급을 반영했습니다. GⅠ은 전원 실제 등록 우마무스메이며 출전 당시 경기장·거리·각질 적성 B 이상입니다. 희소 코스의 NPC 적성 사전 계승도 개인 기록에 남깁니다. 실제 출전·성장·휴식·치료·은퇴 기록을 유지합니다. 랭킹은 세대별 전체/중장거리/스프린터/마일러/더트러로 나누고 모두 올해 전적만 반영합니다. 매년 JRA각 부문과 현창 우마무스메 시상은 개인·목장에 기록됩니다. 뉴스는 월간 GⅠ 우승 소식과 라이벌 우승·목장 GⅠ N승·3관 달성·2관 뒤 3관 도전을 묶어 핵심만 보도합니다. 일상 성장과 모든 입상 기사는 개별 발행하지 않습니다. 동세대 우마무스메 최대 6명이 라이벌입니다. 라이벌보다 높은 착순을 기록하면 1명당 15 스킬 Pt를 받습니다. 목장 랭킹은 소속 전원의 올해 실적을 합산합니다. 플레이어가 주제인 기사는 노란 테두리입니다.</p><h3>예약·칭호·시상식</h3><p>레이스는 한 명당 미래 4개까지 예약하고 당일 조건을 다시 심사해 자동 등록합니다. 네 종류의 3관과 GⅠ N승, JRA 연도별 수상 칭호를 수집할 수 있습니다. 12월 후반 종료 뒤 수상자를 공개 쇼로 발표하며, 수상자마다 뉴스·상금·스킬 Pt를 지급합니다. 24개 목장의 미데뷔·현역 정원은 4명입니다. 개인·목장 평가는 매 경기 평가를 합산합니다. 호성적은 가산되고 부진한 성적은 감점됩니다. GⅠ 1착 평가는 100, 2착 40, 상위 40% 밖 착순은 순위가 낮을수록 더 큰 음수 평가입니다. 현창 우마무스메는 당해 은퇴한 플레이어·NPC의 전 커리어를 함께 심사하며 매년 최대 1명을 선정합니다. 플레이어는 직접 은퇴, NPC는 자동 은퇴도 포함합니다. NPC는 시니어 4년차 12월 후반 시상식 전에 은퇴하며 게임 기준은 잔디 적성 B 이상일 때 GⅠ 6승, 또는 클래식 3관·트리플 티아라+GⅠ 4승, 또는 시니어 봄·가을 중 하나의 3관+GⅠ 5승입니다. 잔디 B 미만이며 더트 B 이상인 경우 GⅠ 5승입니다. 플레이어 자동 은퇴·주니어 자격 미달 은퇴는 후보가 아닙니다. 현창 수상자는 스킬 Pt를 받지 않습니다.</p><h3>계산 참고 자료</h3><p><a href="https://alpha123.github.io/uma-tools/umalator-global/" target="_blank" rel="noopener">Umalator</a> · <a href="http://race-ko.wf-calc.net/" target="_blank" rel="noopener">Uma Race Emulator</a> · <a href="https://amanesinya.github.io/UMA-E-Project/Race-Simulator/" target="_blank" rel="noopener">UMA-E 코스 스킬 분석기</a>. 단일 주자 분석기의 공식을 다인전 경주에 연결한 팬게임이며 각 사이트와 완전히 같은 결과를 보장하지 않습니다.</p><h3>저장·출처</h3><p>이 브라우저에 자동 저장하며 파일 내보내기/불러오기를 지원합니다. 기존 커리어는 개인 능력·자금·카드·기록을 유지하고 새 운영 규칙으로 전환합니다. 과거 결과·다시보기는 당시 기록을 유지하며 새로운 경주부터 변경된 계산을 적용합니다. 생성형 AI 호출 없음. 데이터: Umamusu Wiki /GameTora · 이미지 ©Cygames 및 각 권리자 · 비공식 팬게임.</p></div>`)}
const pages={training:trainingPage,awards:awardsPage,farmRanking:farmRankingPage,rivals:rivalsPage,fusion:fusionHTML,shop:shopPage,home:homePage,news:()=>panel('핵심 뉴스룸 · 월간 GⅠ / 라이벌 우승 / 주요 업적',`<div class="news-feed">${S.news.slice(0,100).map(newsItem).join('')}</div>`),races:racesPage,ranking:rankingPage,runners:runnersPage,medical:medicalPage,supports:supportsPage,factors:factorsPage,scout:scoutPage,finance:financePage,facilities:facilitiesPage,hall:hallPage,dex:dexPage};
function welcome(){return `<div class="welcome"><div class="welcome-copy"><div class="brand"><span class="brand-mark">T✦</span><div>TRACEN <b>FM</b><small>UMA MUSUME RANCH MANAGER</small></div></div><span class="eyebrow">YOUR RANCH. THEIR LEGACY.</span><h1>첫 질주부터,<br>다음 세대까지.</h1><p>미데뷔의 가능성을 현역의 기록으로.<br>은퇴의 유산을 이어가는 우마무스메 목장 운영.</p><div class="welcome-stats"><span><b>271</b>육성 의상</span><span><b>557</b>서포트</span><span><b>24</b>턴 / 시즌</span></div><label>목장 이름<input id="clubName" maxlength="20" value="트레센 목장" aria-label="목장 이름"></label>${button('새 목장 시작 →','new','','primary')}${button('저장 파일 불러오기','import','','text')}${button('운영 가이드','rules','','text')}<small class="welcome-note">로컬 의사결정 AI · 시스템별 독립 난수 · 비공식 팬게임</small></div><div class="welcome-art"><div class="welcome-ring"></div>${image(DB.outfits[0],'welcome-uma',true)}<span>RANCH MANAGEMENT<br>THE FIRST CHAPTER</span></div></div>`}
function render(){if(!DB)return;$('#app').innerHTML=S?(S.startup?starterPage():shell()):welcome()}
function mutate(result,after){if(result?.error){toast(result.error);return false}persist();render();if(result?.message)toast(result.message);if(after)after();return true}
async function advance(){if(S.pendingTurn){showReport();return}if(busy)return;busy=true;const b=document.querySelector('[data-action="advance"]');if(b){b.disabled=true;b.textContent='시즌 처리 중…'}await new Promise(r=>setTimeout(r,40));try{await CareerStore.write(BACKUP,S);S=await processTurn(S);persist();raceTurn=null;busy=false;render();showReport()}catch(e){console.error(e);toast('진행 중 오류가 발생했습니다. 직전 턴 백업이 보관되어 있습니다.')}finally{busy=false}}
function exportSave(){const blob=new Blob([JSON.stringify({format:'tracen-fm',version:1,state:S})],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`tracen-fm-season-${S.year}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('저장 파일을 내보냈습니다.')}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const x=JSON.parse(await input.files[0].text());if(x.format!=='tracen-fm'||x.version!==1||!x.state||!Array.isArray(x.state.runners)||!Array.isArray(x.state.teams)||!Array.isArray(x.state.factors)||!Number.isInteger(x.state.year)||!Number.isInteger(x.state.turn)||x.state.turn<0||x.state.turn>23||x.state.runners.some(u=>!E.outfits.has(u.outfit)||!Array.isArray(u.stats)||u.stats.length!==5||u.stats.some(v=>!Number.isInteger(v)||v<0||v>100))||x.state.runners.filter(u=>u.team===0&&!u.retired).length>4)throw Error('invalid');if(S)await CareerStore.write(BACKUP,S);S=E.resume(x.state);persist();closeModal();render();toast('커리어를 불러왔습니다.')}catch(e){toast('호환되는 TRACEN FM 저장 파일을 선택하세요.')}};input.click()}
