 if(a==='chooseStarter'){const uma=$('[name=starterUma]:checked'),cards=[...document.querySelectorAll('[name=starterSupportV14]:checked')].map(x=>Number(x.value)),factor=$('[name=starterFactor]:checked'),missing=[];if(!uma)missing.push('우마무스메 1명을 선택하세요.');if(cards.length!==2)missing.push('서포트 카드 '+cards.length+'/2장 선택 · '+(cards.length<2?2-cards.length+'장을 더 선택하세요.':'2장만 선택하세요.'));if(!factor)missing.push('시작 인자 1개를 선택하세요.');if(missing.length){const note=$('#starterValidation');note.hidden=false;note.textContent=missing.join(' ');note.focus();toast(missing.join(' '));return}mutate(E.chooseStarter(S,Number(uma.value),cards,Number(factor.value)));return}
