document.addEventListener('change',async e=>{if(e.target.classList.contains('race-style')){const u=S.runners.find(u=>u.id===Number(e.target.dataset.runner)),r=E.racesAt(S,raceTurn??S.turn).find(r=>r.key===e.target.dataset.race),warnings=E.aptWarnings(u,r,Number(e.target.value)),el=$('#apt-warning-'+u.id);el.textContent=warnings.length?'⚠ 적성 부적합(C 이하): '+warnings.join(' · '):'경기장·거리·각질 적성 적합';el.className=warnings.length?'apt-warning':'muted';return}if(e.target.id!=='fastAdvance'||!e.target.value||busy)return;if(S.pendingTurn){showReport();return}const v=e.target.value,n=v==='debut'?Math.max(0,10-S.turn):Number(v);if(!n)return toast('6월 신마전 일정에 도달했습니다.');if(E.own(S).some(u=>u.entry))return toast('등록한 경기를 턴 진행으로 먼저 확인하세요.');busy=true;try{await CareerStore.write(BACKUP,S);let done=0;for(let k=0;k<n;k++){E.advance(S);if(S.pendingTurn.races.length)break;E.finishTurn(S);done++;await new Promise(r=>setTimeout(r,15))}persist();raceTurn=null;render();if(S.pendingTurn)showReport();else toast(done+'턴 진행 · 신마전 출전 등록을 확인하세요.')}catch(err){console.error(err);toast('진행 오류. 백업 복구가 가능합니다.')}finally{busy=false}});
