document.addEventListener('compositionend',e=>{if(e.target.id==='dexSearch'){search=e.target.value.normalize('NFC');$('#dexResults').innerHTML=dexResultsHTML()}});
document.addEventListener('change',e=>{if(e.target.classList.contains('fuse-material')){const c=E.supports.get(Number(e.target.value)),img=e.target.parentElement.querySelector('.fusion-preview');if(c&&img){img.src=c.image;img.alt=c.koCharacter+' · '+c.ko}}});
Promise.all([fetch('database.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json()})]).then(async([d])=>{DB=d;E=UmaRanch.init(DB);const saved=await CareerStore.read(KEY);if(saved?.version===1){if(saved.leagueVersion!==6||saved.activityVersion!==12||saved.honorCriteriaVersion<30||saved.honorCriteriaVersion==null||saved.skillRulesVersion!==31||saved.achievementNewsVersion!==32)await CareerStore.write(BACKUP,saved);S=E.resume(saved);await persist()}render();if(S?.pendingTurn){const next=S.pendingTurn.races.find(id=>!S.results.find(r=>r.id===id)?.presentationComplete);if(next&&S.results.find(r=>r.id===next)?.trace)playRace(next);else showReport()}}).catch(e=>{$('#app').innerHTML='<div class="loading">저장 데이터 또는 게임을 불러오지 못했습니다.<span>기존 데이터는 삭제되지 않았습니다. 새로고침 후 다시 확인하세요.</span></div>';console.error(e)});

function runnerSupports(u,owned){const slot=E.supportSlots(S,u),labels={predebut:'미데뷔',classic:'클래식',senior:'시니어 1년차'};return `<div class="note strong-note">미데뷔 2장 → 클래식 2장 → 시니어 1년차 2장 · 총 6장 영구 장착<br>현재 ${labels[slot.window]||'등록 기간 아님'} · 이번 기간 ${slot.window?slot.used:0}/2 · 전체 ${slot.total}/6</div><p class="note">장착 카드는 해제·교체할 수 없습니다. 고정 능력치 보너스 없음. 훈련 출현 시 노력치 보너스를 제공합니다. 능력 합산은 100을 넘지 않습니다. 주니어 데뷔 후에는 추가 등록할 수 없습니다.</p><div class="support-grid">${u.supportCards.map(x=>{const c=DB.supports.find(c=>c.gameId===x.card);return `<article class="support-card"><div class="market-support-art">${image(c)}${supportTypeBadge(c)}</div><h3>${esc(c.koCharacter)}</h3><p>${c.rarity} · ${labels[x.window]}</p>${button('카드와 스킬 보기','support','data-id="'+c.gameId+'"','small')}</article>`}).join('')}</div>${owned?button('보유 카드에서 장착하기','nav','data-view="supports"','primary'):''}`}

function fusionHTML(){return panel('서포트 합성 · 비용 없음',`<p>미장착 보유 카드만 재료로 사용합니다. 장착 카드는 소모되지 않습니다.</p><div class="fusion-recipes"><article><h3>R 3장 → SR</h3><p>65% 승급 · 무료<br>실패 시 R 1장</p>${button('R 합성','fusionOpen','data-rarity="R"','primary')}</article><article><h3>SR 3장 → SSR</h3><p>45% 승급 · 무료<br>실패 시 SR 1장</p>${button('SR 합성','fusionOpen','data-rarity="SR"','primary')}</article><article><h3>SSR 2장 → SSR 1장</h3><p>무작위 SSR 확정 · 무료<br>재료와 같은 카드도 등장 가능</p>${button('SSR 재합성','fusionOpen','data-rarity="SSR"','primary')}</article></div>`)}

function fieldTable(field,r){return `<div class="table-wrap"><table class="field-table"><thead><tr><th>인기</th><th>출전자</th><th>종류·연차</th><th>각질</th>${statNames.map(n=>'<th>'+n+'</th>').join('')}<th>주로 / 거리 / 각질</th><th></th></tr></thead><tbody>${field.map((u,i)=>`<tr class="${u.team===0?'mine':''}"><td>${u.popularity||i+1}번</td><td><img class="tiny-avatar" src="${esc(u.mob?u.mobImage:E.o(u).image)}" alt="">${esc(u.mob?u.mobName:name(u))}${!u.mob?'<small>'+esc(S.teams[u.team]?.name)+' · #'+u.id+'</small>':''}</td><td>${u.team===0?'내 목장':u.mob?'모브':'우마무스메'}<small>${r.grade===900?'주니어 · 신마전':u.mob?(r.ages.includes(3)?'시니어':r.ages.includes(2)?'클래식':'주니어'):E.ageName(S,u)}</small></td><td>${styleNames[u.style]}</td>${statNames.map((n,k)=>'<td>'+E.value(S,u,k)+'</td>').join('')}<td>${[E.groundIndex(r),E.distType(r)+2,u.style+6].map(k=>UmaFM.apt(u.apt[k])).join(' / ')}</td><td>${button('상세','fieldRunner','data-id="'+esc(u.id)+'" data-key="'+esc(r.key)+'"','small')}</td></tr>`).join('')}</tbody></table></div>`}

function starterPage(){return `<main class="starter-page"><div class="page-heading"><div><span class="eyebrow">THE FIRST CHAPTER · ${esc(S.club)}</span><h1>목장의 첫 동료</h1><p>우마무스메 3명 중 1명 · SSR 10장 중 2장 · 대여 인자 6개 중 1개 선택. 모든 스타팅 개체값은 24입니다.</p></div></div><h2>01. 미데뷔 우마무스메 선택</h2><div class="starter-umas">${S.starterChoices.map((id,i)=>{const o=E.outfits.get(id);return `<label class="starter-choice"><input type="radio" name="starterUma" value="${id}" ${Number(S.starterDraftUma)===id?'checked':''}>${image(o,'',true)}<h3>${esc(o.characterKo)}</h3><p>${esc(o.ko)}</p><small>개체값 24 / 24 / 24 / 24 / 24</small><div class="apt-summary">${o.aptitudes.map((a,k)=>a==='A'?chip(aptNames[k]+' A'):'').join('')}</div>${button('적성 · 스킬 상세 →','starterPreview','data-kind="uma" data-index="'+i+'"','small full')}</label>`}).join('')}</div><h2>02. 첫 SSR 2장 영구 장착 · 주니어 슬롯 2/3 <small id="starterSupportCount">${(S.starterDraftSupports||[]).length}/2 선택</small></h2><div class="starter-cards">${S.starterSupports.map((id,i)=>{const c=DB.supports.find(c=>c.gameId===id);return `<label class="starter-choice"><input type="checkbox" name="starterSupportV14" value="${id}" ${S.starterDraftSupports?.includes(id)?'checked':''}>${image(c)}<h3>${esc(c.koCharacter)}</h3><p>${esc(c.ko)}</p><small>SSR · ${supportTypeBadge(c)} · 훈련 출현 ${Math.round(E.supportAppearance(c)*100)}%</small>${button('배울 수 있는 스킬 →','starterPreview','data-kind="support" data-index="'+i+'"','small full')}</label>`}).join('')}</div>${starterFactorHTML()}<div class="note">선택한 SSR 2장은 영구 장착되며 해제할 수 없습니다. 선택 내용은 브라우저에 자동 저장됩니다.</div><p id="starterValidation" class="starter-validation" role="alert" tabindex="-1" hidden></p>${button('선택 완료 · 목장 개장 →','chooseStarter','','primary full')}</main>`}
function openFusion(rarity){const count=rarity==='SSR'?2:3,cards=DB.supports.filter(c=>c.rarity===rarity&&S.supports[c.gameId]>0),defaults=cards.flatMap(c=>Array(Math.min(count,S.supports[c.gameId])).fill(c.gameId)).slice(0,count);showModal(`<span class="eyebrow">SUPPORT SYNTHESIS · FREE</span><h2>${rarity} 카드 ${count}장 합성</h2><p>${rarity==='SSR'?'무작위 SSR 1장 확정':rarity==='R'?'SR 승급 65%':'SSR 승급 45%'} · 합성 비용 없음 · 재료 소모</p><div class="fusion-material-grid">${Array.from({length:count},(_,i)=>`<label class="fusion-material-card"><b>재료 ${i+1}</b>${defaults[i]?image(E.supports.get(defaults[i]),'fusion-preview'):'<div class="empty">재료 없음</div>'}<select class="fuse-material" aria-label="합성 재료 ${i+1}">${cards.map(c=>`<option value="${c.gameId}" ${defaults[i]===c.gameId?'selected':''}>${esc(c.koCharacter)} · ${esc(c.ko)} ×${S.supports[c.gameId]}</option>`).join('')}</select></label>`).join('')}</div>${button('무료 합성 실행','fuseConfirm',`data-rarity="${rarity}" ${defaults.length===count?'':'disabled'}`,'primary full')}`)}
function openFusionResult(result){const c=E.supports.get(result.card);showModal(`<h2>${result.rarity==='SSR'||result.recycled?'SSR 재합성 완료':result.success?'합성 성공':'승급 실패 · 동급 반환'}</h2><div class="synthesis-result">${image(c)}<h3>${c.rarity} · ${esc(c.koCharacter)}</h3>${supportTypeBadge(c)}<p>${esc(c.ko)}</p></div>${button('확인','close','','primary full')}`)}
function openFieldRunner(id,key){const r=E.racesAt(S).find(r=>r.key===key),u=r?E.raceField(S,r).find(u=>String(u.id)===id):null;if(!u)return;showModal(`<span class="eyebrow">RACE RUNNER · 인기 ${u.popularity}번</span><div class="runner-detail-head"><img class="detail-stand" src="${esc(u.mob?u.mobImage:E.o(u).art||E.o(u).image)}" alt=""><div><h2>${esc(u.mob?u.mobName:name(u))}</h2><p>${u.mob?'GameTora 모브 · '+esc(u.mobOriginal):esc(S.teams[u.team]?.name||'초청 우마무스메')}</p>${statGrid(u)}</div></div>${aptitudeHTML(u)}<p class="note">${u.mob?'원본 이름·주로·선호 거리 기반. 능력치는 대회 등급에 맞춘 FM 생성값입니다.':'보정 전 기초능력입니다. 컨디션·연차 보정은 레이스에서만 적용됩니다.'}</p><div class="skill-pills">${E.allSkills(u).map(i=>skillButton(i)).join('')}</div>${button('출전 명단으로','race','data-key="'+esc(key)+'" data-turn="'+S.turn+'"','primary')}`)}
function nextRaceButton(current){const id=S.pendingTurn?.races.find(id=>id!==current&&!S.results.find(r=>r.id===id)?.presentationComplete);return id?button('다음 경기 1분 관전 →','watchNext','data-id="'+id+'"','primary'):''}
function skillMechanicsHTML(id){const info=E.skillMechanics(id);if(!info)return '';return `<h3 class="subheading">경주 엔진 연동</h3><div class="tags">${info.effects.map(e=>chip(esc(e))).join('')}</div><p class="note">고유·계승 고유기와 패시브는 조건 충족 시 적용합니다. 일반·레어·진화 스킬은 참고 시뮬레이터의 지능 발동률 판정을 거칩니다. 각질·거리·주로·코너·순위 조건을 실제 경주 중 검사하며, 선행 조건은 충족 이력을 기억합니다.</p><details class="source-details"><summary>효과 지속시간 · 재발동 · 원본 조건</summary>${info.conditions.map((c,i)=>`<p>${i+1}. 지속 ${esc(c.duration)} · ${esc(c.cooldown)}<br><small>${esc(c.condition||'상시')}${c.precondition?'<br>선행 조건: '+esc(c.precondition):''}</small></p>`).join('')}</details>`}

function skillCategoryBadges(id){const style={'회복':'heal','가속':'accel','속도':'speed','복합':'composite','패시브':'passive','디버프':'debuff','스타트':'gate'};return `<span class="skill-categories">${E.skillCategories(id).map(t=>`<span class="skill-category cat-${style[t]||'other'}">${t}</span>`).join('')}${E.skillRestrictions(id).map(t=>`<span class="skill-category cat-restriction">${esc(t)}</span>`).join('')}</span>`}

function raceSkillChecksHTML(result){const rows=result.rows.filter(x=>x.team===0&&x.skillChecks?.length);if(!rows.length)return '';const labels={activated:'발동',wisdom:'지능 판정 불발',condition:'조건 미충족'};return `<h3 class="subheading">내 우마무스메 스킬 발동 점검</h3><p class="note">의상 고유기와 장착한 획득 스킬·계승기만 검사합니다. 해금만 했거나 장착하지 않은 스킬은 경주에 적용되지 않습니다.</p>${rows.map(row=>`<h4>${esc(row.name)}</h4>${row.skillChecks.map(c=>`<div class="skill-row">${skillButton(c.id)}${chip(labels[c.state],c.state==='activated'?'gold':'')}</div>`).join('')}`).join('')}`}

function awardHTML(a){return `<article class="award-card">${a.outfit?image(E.outfits.get(a.outfit),'avatar'):''}<div><small>${a.year} JRA AWARDS</small><b>${esc(a.title)}</b><span>${esc(a.name)} · ${esc(S.teams[a.team??0]?.name)}</span>${a.runner?button('개인 기록','runner','data-id="'+a.runner+'" data-tab="record"','small'):''}</div></article>`}

function shopPage(){return panel('목장 상점',`<article class="shop-product"><span class="shop-icon">↺</span><div><h2>노력치 초기화권</h2><p>분배한 노력치를 전부 미분배 포인트로 회수합니다. 총 노력치는 보존되며 개체값·서포트·인자 보너스는 유지됩니다. 우마무스메 능력 화면에서 사용합니다.</p><b>${money(E.resetPrice)} · 보유 ${S.inventory?.evReset||0}개</b></div>${button('1개 구매','buyReset','','primary')}</article>`) }

function openOutfitPreview(id){const o=E.outfits.get(Number(id));if(!o)return;showModal(`<div class="runner-detail-head">${image(o,'detail-stand',true)}<div><span class="eyebrow">OUTFIT REPORT</span><h2>${esc(o.characterKo)}</h2><p>${esc(o.ko)}</p></div></div><h3 class="subheading">기초 적성</h3>${aptitudeHTML({apt:o.aptitudes.map(a=>UmaFM.APT.indexOf(a))})}<h3 class="subheading">고유기</h3><div class="skill-pills">${o.uniqueSkills.map(skillWithDescription).join('')}</div><h3 class="subheading">내장 레어 스킬</h3><div class="skill-pills">${skillPillsHTML31(o.goldSkills)}</div>${outfitEvolutionHTML(o)}`)}

function skillDescriptionToggle(id){
  const desc=E.skills.get(Number(id))?.desc?.trim();
  return desc?`<details class="runner-skill-description"><summary>스킬 설명</summary><p>${esc(desc)}</p></details>`:'';
}
function skillWithDescription(id){
  return `<div class="skill-summary-card">${skillButton(id)}${skillDescriptionToggle(id)}</div>`;
}
function skillButtonSafe(id){return skillButton(id)}

function previewStarter(kind,index){if(kind==='factor'){index=(Number(index)+S.starterFactorChoices.length)%S.starterFactorChoices.length;const f=S.starterFactorChoices[index];starterPreview={kind,index};showModal(`<div class="preview-pager">${button('← 이전','starterPreview','data-kind="factor" data-index="'+(index-1)+'"','small')}<b>대여 인자 ${index+1}/${S.starterFactorChoices.length}</b>${button('다음 →','starterPreview','data-kind="factor" data-index="'+(index+1)+'"','small')}</div>${factorCard(f)}<p>청·적·녹 2성 / 백 3개 · 1회 대여 · 계승 후 반환</p>${button('이 후보 선택','starterPick','data-kind="factor" data-id="'+f.id+'"','primary full')}`);return}const list=kind==='uma'?S.starterChoices:S.starterSupports;index=(Number(index)+list.length)%list.length;starterPreview={kind,index};const o=kind==='uma'?E.outfits.get(list[index]):E.supports.get(list[index]);showModal(`<div class="preview-pager">${button('← 이전','starterPreview',`data-kind="${kind}" data-index="${index-1}"`,'small')}<b>${kind==='uma'?'우마무스메':'SSR 서포트'} ${index+1} / ${list.length}</b>${button('다음 →','starterPreview',`data-kind="${kind}" data-index="${index+1}"`,'small')}</div><div class="runner-detail-head">${image(o,kind==='uma'?'detail-stand':'large-card',kind==='uma')}<div><span class="eyebrow">STARTER DETAILS</span><h2>${esc(o.characterKo||o.koCharacter)}</h2><p>${esc(o.ko)}</p>${kind==='uma'?'<p>고정 개체값 24 / 24 / 24 / 24 / 24</p>':'<p>SSR · '+esc(E.supportTypeName(o))+' · 영구 장착</p>'}</div></div>${kind==='uma'?`<h3>기초 적성</h3>${aptitudeHTML({apt:o.aptitudes.map(a=>UmaFM.APT.indexOf(a))})}<h3>고유기</h3><div class="skill-pills">${o.uniqueSkills.map(skillWithDescription).join('')}</div><h3>내장 금딱기 · 진화기</h3><div class="skill-pills">${[...o.goldSkills,...o.evolutionSkills.map(e=>e.new)].map(skillButtonSafe).join('')}</div>`:` ${supportRareHTML(o)}<h3>전체 해금 스킬 · ${o.skills.length}종</h3><div class="skill-pills">${o.skills.map(skillButtonSafe).join('')}</div>`}${button('이 후보 선택','starterPick',`data-kind="${kind}" data-id="${list[index]}"`,'primary full')}`)}

function runnerEVHTML(u){const total=u.ev.reduce((a,b)=>a+b,0);return `<section class="ev-allocation"><div class="section-label"><h3>노력치 포인트</h3><b class="gold-text">미분배 ${u.evPoints} Pt · 분배 ${total}/200</b></div><p class="note">훈련 턴마다 ${S.fac.training+1} Pt 획득. 미분배+분배 합계 200에서 종료됩니다. 아래에는 이번에 추가할 포인트를 입력하세요. 1 Pt당 능력치 1, 합산 능력치는 100에서 제한됩니다. 분배는 초기화권 없이 되돌릴 수 없습니다.</p><div class="ev-plan">${statNames.map((n,i)=>`<label>${n}<small>현재 노력치 ${u.ev[i]}</small><input type="number" id="alloc-${i}" min="0" max="${Math.min(u.evPoints,100-u.ev[i])}" value="0" aria-label="${n} 추가 노력치"></label>`).join('')}</div>${button('포인트 확정 분배','allocateEV','data-id="'+u.id+'"','primary')}${button('초기화권 사용 · 보유 '+(S.inventory?.evReset||0),'resetPrompt','data-id="'+u.id+'"','text')}<h3>자동 컨디션 관리</h3><p class="note">컨디션 50 미만이면 회복 모드 → 85 이상이 되면 자동 훈련 재개. 50~84에서는 직전 모드를 유지합니다. 출전·치료 턴은 훈련하지 않습니다.</p><div class="training-controls"><label>지속 행동<select id="runnerPlan" ${u.status==='undebuted'?'disabled':''}><option value="auto" ${u.plan!=='rest'?'selected':''}>자동 훈련·휴식</option><option value="rest" ${u.plan==='rest'?'selected':''}>휴식 고정</option></select></label>${button('행동 저장','plan','data-id="'+u.id+'"','small')}</div><p>${u.status==='undebuted'?'6월 신마전 참가 후 훈련이 시작됩니다.':esc(u.autoState||'자동 관리')}</p></section>`}

function runnerRecords(u){return `<h3 class="subheading">기간별 기록</h3><div class="career-periods">${['junior','classic','senior'].map(k=>{const r=E.recordFor(u,k);return `<article><h3>${{junior:'주니어',classic:'클래식',senior:'시니어'}[k]}</h3><b>${r.starts}전 ${r.wins}승 · ${r.points} PT</b><p>${r.titles.map(t=>esc(t.race)).join(' · ')||'주요 우승 없음'}</p></article>`}).join('')}</div><h3 class="subheading">전체 출전 기록</h3>${recordTable(u.history)}`}

function rankRecord(u,index){const h=E.annualRecord(S,u,rankDisc).recent[Number(index)];if(!h)return;showModal(`<span class="eyebrow">${E.calendarYear(S)} RECENT RESULT</span><h2>${esc(name(u))} · ${h.pos}착</h2><p>${date(h.at%24,Math.floor(h.at/24)+1)}</p><h3>${esc(h.race)}</h3><p>${esc(h.track||'')} · ${h.terrain===2?'더트':'잔디'} ${h.distance}m · 인기 ${h.popularity||'—'}번 · ${styleNames[h.style]||'기존 기록'}</p><p>${esc(S.teams[u.team]?.name)} · ${h.points} PT</p>${button('전체 개인 기록','runner','data-id="'+u.id+'" data-tab="record"','primary')}`)}

document.addEventListener("change",e=>{if(e.target.name==="starterUma"||e.target.name==="starterSupport"||e.target.name==="starterFactor"){S[e.target.name==="starterUma"?"starterDraftUma":e.target.name==="starterFactor"?"starterDraftFactor":"starterDraftSupport"]=Number(e.target.value);persist()}});

function dexResultsHTML(){if(dexTab==='courses')return courseCatalogueHTML();if(dexTab==='titles')return titleCatalogueHTML();const rows=E.dexSearch(dexTab,search,dexFilters),shown=rows.slice(0,dexLimit);return `<p class="note">${rows.length}종 검색됨 · ${shown.length}종 표시${dexTab==='outfits'?' · 선택 조건의 적성 '+UmaFM.apt(Number(dexFilters.apt))+' 이상':dexFilters.generic?' · 범용 스킬 포함':' · 선택한 각질·거리·주로 전용 조건으로 분류'}</p>${dexTab==='skills'?`<div class="dex-skill-grid">${shown.map(sk=>`<article>${skillButton(sk.id)}<p>${esc(sk.desc)}</p><small>${sk.cost??'—'} Pt · ${sk.rarity===6?'진화':sk.rarity===2?'레어':sk.rarity>=3?'고유':'노말'}</small></article>`).join('')}</div>`:`<div class="dex-grid ${dexTab==='supports'?'support-dex-grid':''}">${shown.map(o=>`<article class="dex-entry"><button class="dex-card" data-action="dexItem" data-id="${o.gameId}" data-kind="${dexTab}"><div class="market-support-art">${image(o)}${dexTab==='supports'?supportTypeBadge(o):''}</div><b>${esc(o.characterKo||o.koCharacter)}</b><small>${esc(o.ko)}</small></button>${dexTab==='supports'?supportRareHTML(o,false):`<div class="tags">${o.aptitudes.map((a,i)=>i>=2&&a==='A'?chip(aptNames[i]+' '+a):'').join('')}</div>`}</article>`).join('')}</div>`}${rows.length>shown.length?button('더 보기 · '+(rows.length-shown.length)+'종 남음','dexMore','','full'):''}${rows.length?'':empty('검색어 또는 분류 조건을 바꿔 보세요.')}`}

function starterFactorHTML(){return `<h2>03. 시작 대여 인자 · 6개 중 1개</h2><p class="note">청·적·녹 2성 고정 / 백인자 3개 고정 / 1회 사용 후 반환. 백인자는 각 50% 확률로 즉시 습득합니다.</p><div class="starter-factors">${S.starterFactorChoices.map((f,i)=>`<section class="starter-factor-option"><label><input type="radio" name="starterFactor" value="${f.id}" ${Number(S.starterDraftFactor)===f.id?'checked':''}>${esc(f.name)} 대여 인자 선택</label>${factorCard(f)}${button('인자 상세 →','starterPreview','data-kind="factor" data-index="'+i+'"','small full')}</section>`).join('')}</div>`}

function cashflowHTML(f,pending=false,compact=false){const lines=(items,negative)=>`<div class="cashflow-items">${(items||[]).map(x=>`<div><span>${esc(x.label)}${x.projected?' (예정)':''}</span><b class="${negative?'red':''}">${negative?'−':'+'}${money(x.amount)}</b></div>`).join('')||'<p class="note">해당 내역 없음</p>'}</div>`;const breakdown=`<div class="cashflow-breakdown">${!compact||f.incomeItems?.length?`<section><h4>수입 내역</h4>${lines(f.incomeItems,false)}</section>`:''}${!compact||f.expenseItems?.length?`<section><h4>지출 내역</h4>${lines(f.expenseItems,true)}</section>`:''}</div><p class="note">경매 입찰 때 지출한 예치금은 총지출에, 유찰 반환금은 총수입에 포함합니다. 낙찰 때 같은 금액을 다시 지출하지 않습니다.${f.forecast?' 월 후반 팬 수입·유지비·이자는 예정 금액입니다.':''}</p>`;return `<section class="cashflow-panel"><div class="section-label"><h3>현금 흐름 · ${f.forecast?'예상 결산':pending?'이번 턴 확정 결산':'직전 확정 결산'}</h3>${chip(f.forecast?'미정산 포함':'장부 합계')}</div><div class="cashflow-grid"><div><small>총수입</small><strong>+${money(f.income)}</strong></div><div><small>총지출</small><strong class="red">${f.expense?'−'+money(f.expense):money(0)}</strong></div><div><small>순현금 흐름</small><strong class="${f.net<0?'red':''}">${f.net>0?'+':''}${money(f.net)}</strong></div></div>${compact?f.incomeItems?.length||f.expenseItems?.length?`<details class="report-ledger"><summary>수입·지출 상세</summary>${breakdown}</details>`:'':breakdown}</section>`}
function inheritanceHistoryHTML(u){return `<h3 class="subheading">인자 계승 이력 · 실제 반영 내역</h3>${(u.inheritanceHistory||[]).slice().reverse().map(h=>`<article class="inheritance-history"><header><b>${esc(h.factor.name)} · ${h.rental?'1회 대여 · 반환됨':'고유 / 사전 육성'}</b><small>${date(h.at%24,Math.floor(h.at/24)+1)} · ${esc(({junior:'주니어',classic:'클래식',senior:'시니어 1년차'})[h.period]||h.period)}${h.seeded?' · 입장 전 육성 기록':''}</small></header><p>청 ${statNames[h.factor.blue.stat]} ${'★'.repeat(h.factor.blue.stars)} / 적 ${aptNames[h.factor.red.apt]} ${'★'.repeat(h.factor.red.stars)} / 백 ${h.factor.white.length}개</p><p><b>능력 보너스</b> ${h.statBonus.map((v,i)=>v?statNames[i]+' +'+v:'').filter(Boolean).join(' · ')||'변화 없음'}${h.beforeStats&&h.afterStats?'<br>실제 능력 '+h.beforeStats.map((v,i)=>statNames[i]+' '+v+'→'+h.afterStats[i]).join(' / '):''}</p><p><b>적성</b> ${h.aptChanges.map(c=>aptNames[c.index]+' '+UmaFM.apt(c.before)+'→'+UmaFM.apt(c.after)).join(' · ')||'변화 없음'}</p><b>즉시 습득 백인자 스킬</b><div class="skill-pills">${h.acquired.map(i=>skillButton(i)).join('')||'신규 습득 없음'}</div><b>계승 고유기 해금</b><div class="skill-pills">${h.greenUnlocked.map(i=>skillButton(i)).join('')||'신규 해금 없음'}</div></article>`).join('')||'<p class="note">새 규칙 적용 후 사용한 인자부터 기록합니다. 과거 계승의 실제 확률 결과는 복원하지 않습니다.</p>'}`}
function nearbyRivalsHTML(u){if(!u)return '';const rows=E.nearbyRivals(S,u);return panel(esc(name(u))+' · 동세대 라이벌 '+rows.length+'명',`<p class="note">동세대 우마무스메 중 최대 6명이 고정 라이벌로 선정됩니다. 같은 경주에서 라이벌보다 먼저 결승선을 통과하면 1명당 추가 스킬 Pt 15를 얻습니다. 동일 개체의 성장·출전·부상과 랭킹이 연결됩니다.</p><div class="rival-grid">${rows.map(({runner:v,record:r,rank})=>`<article class="rival-card"><button class="rank-profile" data-action="runner" data-id="${v.id}">${runnerHead(v)}<small>전체 ${rank}위 · ${esc(S.teams[v.team].name)}<br>${E.ageName(S,v)} · 개체 #${v.id}</small></button><p><b>${r.points} PT</b> · ${r.starts}전 ${r.wins}승 · GⅠ ${r.g1}승</p><small>${v.medical?esc(v.medical.name||'치료 중'):'컨디션 '+v.fitness}</small><div class="recent-five">${(r.recent||[]).map(h=>`${(()=>{const result=S.results.find(r=>r.at===h.at&&r.race.key===h.key);return result?button(h.pos+'착 · '+esc(h.race),'result','data-id="'+result.id+'"','small'):chip(h.pos+'착 · '+esc(h.race))})()}`).join('')||'올해 출전 없음'}</div>${button('능력 · 적성 · 전체 기록','runner','data-id="'+v.id+'"','small full')}</article>`).join('')}</div>`,button('라이벌 전체 보기','nav','data-view="rivals"','text'))}
function rivalsPage(){return E.own(S).map(nearbyRivalsHTML).join('')||empty('소속 우마무스메를 먼저 선택하세요.')}
let farmRankingPeriod='year';
function farmRankingPage(){
 const allTime=farmRankingPeriod==='history',rows=E.farmRanking(S,allTime).filter(r=>!r.team.themeKey),shown=rows.slice(0,25);
 for(const r of rows.slice(25))if(r.team.id===0)shown.push(r);
 const tabs=[['year','올해'],['history','역대']].map(([key,label])=>button(label,'farmRankingPeriod',`data-key="${key}"`,farmRankingPeriod===key?'active':'')).join('');
 return `<div class="tabs page-tabs">${tabs}</div>`+panel(allTime?'역대 목장 랭킹':E.calendarYear(S)+'년 목장 랭킹',`<p class="note">상위 25개 목장과 우리 목장 · 현재 현역 최대 4명</p><div class="farm-ranking-list">${shown.map(r=>{
  const members=E.team(S,r.team.id).filter(u=>!u.mob&&!u.released&&u.status==='active').slice(0,4);
  return `<article class="farm-rank-row ${r.team.id===0?'farm-rank-own':''}"><b class="farm-rank-number">${rows.indexOf(r)+1}</b><div>${button(esc(r.team.name),'farmRankingDetail',`data-id="${r.team.id}"`,'small')}<small>${r.team.theme?esc(r.team.theme)+' · ':''}${r.points} Pt · ${r.starts}전 ${r.wins}승 · GⅠ ${r.g1}승</small></div><div class="farm-rank-members">${members.map(u=>button(image(E.o(u))+`<span>${esc(E.o(u).characterKo)}</span>`,'runner',`data-id="${u.id}" data-tab="record"`,'small')).join('')||'<small>현재 현역 없음</small>'}</div></article>`;
 }).join('')}</div>`);
}
window.addEventListener('click',event=>{
 const b=event.target.closest('[data-action="farmRankingPeriod"],[data-action="farmRankingDetail"]');
 if(!b||!S||busy)return;
 event.stopImmediatePropagation();
 if(b.dataset.action==='farmRankingPeriod'){farmRankingPeriod=b.dataset.key;render();return;}
 const team=S.teams[Number(b.dataset.id)];
 if(!team)return;
 const members=E.team(S,team.id).filter(u=>!u.mob&&!u.released);
 const meetings=team.id===0?[]:S.results.filter(r=>r.rows.some(x=>x.team===0)&&r.rows.some(x=>x.team===team.id));
 showModal(`<h2 class="modal-title">${esc(team.name)}</h2>${team.theme?`<p>${esc(team.theme)}</p>`:''}<h3>현재 소속</h3><div class="farm-rank-members">${members.map(u=>button(image(E.o(u))+`<span>${esc(E.o(u).characterKo)}${u.status==='undebuted'?' · 미데뷔':''}</span>`,'runner',`data-id="${u.id}" data-tab="record"`,'small')).join('')||empty('현재 소속 없음')}</div>${team.id!==0?`<h3>우리 목장과의 최근 맞대결</h3><div class="farm-rank-members">${meetings.slice(0,5).map(r=>button(esc(r.race.name)+' 결과','result',`data-id="${r.id}"`,'small')).join('')||empty('보존된 맞대결 기록이 없습니다.')}</div>`:''}`);
},true);

function capacityDetailsHTML(){const p=E.leaguePlan,stages=[1,2,3],counts=(k,filter)=>p.rosters[k].filter(filter).length;return `<details class="capacity-details"><summary>경기장·거리·각질별 인원 계산 상세</summary><p class="note">주로·거리의 필요 인원은 해당 조합이 3턴 안에 요구하는 출전 자리와 25% 여유를 반영한 수입니다. 한 우마무스메가 여러 코스에 적합할 수 있으므로 합계는 세대 정원과 다릅니다. 각질은 고정 정원이 아닌 주력 각질의 구성입니다.</p><div class="table-wrap"><table><thead><tr><th>적성 조합</th>${stages.map(k=>'<th>'+['','주니어','클래식','시니어'][k]+' 필요 / 편성</th>').join('')}</tr></thead><tbody>${p.tags.map(tag=>{const [ground,d]=tag.split(':').map(Number);return `<tr><td>${ground===1?'잔디':'더트'} · ${aptNames[d+2]}</td>${stages.map(k=>'<td>'+p.roleNeeds[k][tag]+' / '+counts(k,u=>u.apt[ground===1?0:1]>=5&&u.apt[d+2]>=5)+'명</td>').join('')}</tr>`}).join('')}${styleNames.map((n,i)=>`<tr><td>주력 ${n}</td>${stages.map(k=>'<td>'+counts(k,u=>u.apt.slice(6).indexOf(Math.max(...u.apt.slice(6)))===i)+'명</td>').join('')}</tr>`).join('')}</tbody></table></div><p class="note">계산은 연초 편성 기준입니다. 실제 출전은 개인의 현재 적성·컨디션·회복·일정을 검사합니다.</p></details>`}

let raceAll=false,trainingId=null,ceremonyStep=0;
function reservationsHTML(){return panel('예약된 레이스 · 1명당 최대 4개',E.own(S).map(u=>`<div class="reservation-row">${runnerHead(u)}<div>${(u.reservations||[]).map(x=>`<div><b>${esc(x.name)}</b> · ${date(x.at%24,Math.floor(x.at/24)+1)} · ${styleNames[x.style]} ${button('예약 취소','cancelReservation',`data-id="${u.id}" data-at="${x.at}"`,'small')}</div>`).join('')||'<span class="muted">예약 없음</span>'}</div></div>`).join('')+'<p class="note">예약 당일 자동 등록합니다. 부상·컨디션·출전 조건을 다시 확인하며, 통과하지 못하면 예약 취소 사유를 활동 기록에 남깁니다.</p>')}
function trainingPage(){const own=E.own(S),u=own.find(x=>x.id===trainingId)||own[0];if(!u)return empty('우마무스메를 먼저 영입하세요.');return `<div class="tabs">${own.map(x=>button(esc(name(x)),'trainingSelect','data-id="'+x.id+'"',x===u?'active':'')).join('')}</div>${panel('트레이닝 · '+esc(name(u)),runnerHead(u)+statGrid(u)+runnerEVHTML(u).replace('data-action="allocateEV"','data-action="trainingAllocate"').replace('data-action="plan"','data-action="trainingPlan"'))}`}
function rewardReceiptHTML(result){return `<div class="reward-receipts">${result.rows.filter(x=>x.team===0).map(x=>x.rewards?`<article><small>${esc(x.name)} · ${x.pos}착 보상</small><h3>${money(x.rewards.prize)}</h3><p>서포트 뽑기권 <b>+${x.rewards.tickets}장</b> · 스킬 Pt <b>+${x.rewards.skillPoints}</b>${x.rewards.rivalPoints?' (라이벌 보너스 +'+x.rewards.rivalPoints+' 포함)':''}</p>${(x.newTitles||[]).map(t=>chip(esc(t))).join('')}</article>`:'<p class="note">이전 경기: 상세 보상 내역 미기록</p>').join('')}</div>`}
function financeChartHTML(){const data=E.financeRows(S).slice(-financeRange);if(!data.length)return '';const W=960,left=80,right=935,w=right-left,x=i=>left+(i+.5)*w/data.length,lo=Math.min(0,...data.map(r=>r.balance)),hi=Math.max(1,...data.map(r=>r.balance)),y=v=>195-(v-lo)/(hi-lo||1)*155,flowMax=Math.max(1,...data.flatMap(r=>[r.income||0,r.expense||0])),fy=v=>180-v/flowMax*135,fmt=n=>Math.abs(n)>=10000?(n/10000).toFixed(Math.abs(n)>=100000?0:1)+'만':Math.round(n).toLocaleString(),tick=i=>i===0||i===data.length-1||i%Math.max(1,Math.ceil(data.length/6))===0,when=r=>`${Math.floor(r.at%24/2)+1}월 ${r.at%2?'후':'전'}`,tip=r=>`${date(r.at%24,Math.floor(r.at/24)+1)}${r.open?' · 진행 중':''} / 잔액 ${money(r.balance)} / 수입 ${money(r.income||0)} / 지출 ${money(r.expense||0)}`,sum=k=>data.reduce((n,r)=>n+(r[k]||0),0),bw=Math.min(18,w/data.length*.28),path=data.map((r,i)=>`${x(i)},${y(r.balance)}`).join(' ');return panel('재정 대시보드',`<div class="finance-chart-toolbar"><p>잔액과 수입·지출을 별도 눈금으로 표시합니다.</p><label>기간<select id="financeRange">${[12,24,48].map(n=>`<option value="${n}" ${financeRange===n?'selected':''}>최근 ${n}턴</option>`).join('')}</select></label></div><div class="finance-period-totals"><article><small>선택 기간 총수입</small><b>+${money(sum('income'))}</b></article><article><small>선택 기간 총지출</small><b class="red">−${money(sum('expense'))}</b></article><article><small>선택 기간 순수입</small><b class="${sum('income')<sum('expense')?'red':''}">${money(sum('income')-sum('expense'))}</b></article></div><div class="finance-chart-block"><h3>운영 자금 추이 <small>원</small></h3><div class="finance-svg-scroll"><svg viewBox="0 0 960 235" role="img" aria-label="운영 자금 잔액 추이">${[0,.25,.5,.75,1].map(q=>{const v=lo+q*(hi-lo);return `<line x1="${left}" x2="${right}" y1="${y(v)}" y2="${y(v)}" stroke="#e3e9e1"/><text x="${left-10}" y="${y(v)+4}" text-anchor="end">${fmt(v)}</text>`}).join('')}<line x1="${left}" x2="${right}" y1="${y(0)}" y2="${y(0)}" stroke="#829b86"/><polyline points="${path}" fill="none" stroke="#285a49" stroke-width="3"/>${data.map((r,i)=>`<g><title>${esc(tip(r))}</title><circle cx="${x(i)}" cy="${y(r.balance)}" r="${r.open?5:3.5}" fill="${r.open?'#e6c47c':'#285a49'}"/>${tick(i)?`<text x="${x(i)}" y="222" text-anchor="middle">${when(r)}</text>`:''}</g>`).join('')}</svg></div></div><div class="finance-chart-block"><h3>턴별 수입 · 지출 <small><span class="income-dot">● 수입</span> <span class="expense-dot">● 지출</span></small></h3><div class="finance-svg-scroll"><svg viewBox="0 0 960 220" role="img" aria-label="턴별 수입과 지출 막대그래프">${[0,.5,1].map(q=>`<line x1="${left}" x2="${right}" y1="${fy(flowMax*q)}" y2="${fy(flowMax*q)}" stroke="#e3e9e1"/><text x="${left-10}" y="${fy(flowMax*q)+4}" text-anchor="end">${fmt(flowMax*q)}</text>`).join('')}${data.map((r,i)=>`<g opacity="${r.open?.65:1}"><title>${esc(tip(r))}</title><rect x="${x(i)-bw-1}" y="${fy(r.income||0)}" width="${bw}" height="${180-fy(r.income||0)}" fill="#6e9b57" rx="2"/><rect x="${x(i)+1}" y="${fy(r.expense||0)}" width="${bw}" height="${180-fy(r.expense||0)}" fill="#c17d60" rx="2"/>${tick(i)?`<text x="${x(i)}" y="207" text-anchor="middle">${when(r)}</text>`:''}</g>`).join('')}</svg></div></div><p class="note">점을 가리키면 날짜와 정확한 금액을 확인할 수 있습니다. 노란 점·옅은 막대는 진행 중인 턴입니다. 수입에는 유찰 반환금, 지출에는 경매 예치금을 포함합니다.</p><details class="finance-exact"><summary>턴별 정확한 금액 · ${data.length}턴</summary><div class="table-wrap"><table><tr><th>날짜</th><th>잔액</th><th>수입</th><th>지출</th><th>순수입</th></tr>${data.slice().reverse().map(r=>`<tr><td>${date(r.at%24,Math.floor(r.at/24)+1)}${r.open?' · 진행 중':''}</td><td>${money(r.balance)}</td><td>+${money(r.income||0)}</td><td class="red">−${money(r.expense||0)}</td><td>${money((r.income||0)-(r.expense||0))}</td></tr>`).join('')}</table></div></details>`)}
function awardsPage(){return `<section class="awards-banner"><span class="eyebrow">THE YEAR'S FINEST</span><h2>JRA AWARDS</h2><p>매년 12월 후반 종료 후 · 한 해의 질주를 기리는 공개 시상 쇼</p><p>연도대표 ₩100,000 / 150 Pt · 부문상 ₩50,000 / 80 Pt · 현창 우마무스메 ₩100,000 / 스킬 Pt 없음</p></section>${(S.awards||[]).map(c=>panel(c.year+' JRA 연말 시상식',`<div class="award-grid">${c.items.map(a=>`<div class="award-entry">${awardHTML(a)}<small class="award-reward">상금 ${money(a.prize||0)} · 스킬 Pt +${a.skillPoints||0}</small></div>`).join('')}</div>`,button('시상 쇼 관람 →','ceremony','data-year="'+c.year+'"','primary'))).join('')||empty('첫 연말 시상식은 12월 후반 결산 후 열립니다.')}`}
function openCeremony(year){const c=S.awards.find(x=>x.year===year);if(!c)return;const index=Math.min(ceremonyStep,c.items.length),a=c.items[index],end=!a;showModal(`<section class="ceremony-show"><header><span class="eyebrow">${year} JRA AWARDS · ${end?'FINALE':(index+1)+' / '+c.items.length}</span><h2>${end?'올해의 모든 별들에게':esc(a.title)}</h2></header>${a&&E.outfits.has(a.outfit)?image(E.outfits.get(a.outfit),'ceremony-portrait',true):'<div class="ceremony-star">★</div>'}<div class="ceremony-info"><h1>${end?'시상식 폐막':esc(a.name)}</h1><p>${end?'다음 시즌에도 새로운 전설이 시작됩니다.':esc(S.teams[a.team]?.name||'')}</p>${a?`<div class="ceremony-prize">상금 ${money(a.prize||0)} · 스킬 Pt +${a.skillPoints||0}<br><small>수상 확정 시 지급 완료 · 다시 관람해도 중복 지급되지 않습니다.</small></div>`:''}</div><footer>${end?button('시상식 마치기','ceremonyDone','','lime'):button('다음 수상 발표 →','ceremonyNext','data-year="'+year+'"','lime')}</footer></section>`)}

function raceReadinessHTML(u,r){const q=E.raceReadiness(S,u,r);return `<div class="race-readiness ${q.margin<0?'warn':''}"><b>종반 전력 스퍼트 준비 · ${q.margin>=0?'기본 HP 여유':'기본 HP 부족 가능'}</b><span>계산 HP ${q.hp} · 예상 필요량 ${q.needed} · 여유 ${q.margin>=0?'+':''}${q.margin}</span><small>양호 마장·스킬 없는 기준 추정입니다. 실제 경사·날씨·회복 발동·흥분·경합에 따라 달라집니다.</small></div>`}

function supportRareHTML(c,showType=true){const ids=E.supportRareSkills(c);return `${showType?supportTypeBadge(c):''}<div class="support-rare"><small>제공 레어 스킬</small><div class="skill-pills">${ids.map(skillButtonSafe).join('')||'<span class="muted">제공 없음</span>'}</div></div>`}
function outfitEvolutionHTML(o,compact=false){return `<div class="scout-evolutions ${compact?'compact':''}"><h4>${compact?'이 의상의 진화기':'내장 레어 → 진화기'}</h4>${o.evolutionSkills.map(e=>`<div class="evolution-path">${compact?'':skillButtonSafe(e.old)+'<span>→</span>'}${skillButtonSafe(e.new)}</div>`).join('')||'<small>등록된 진화기 없음</small>'}${compact?'':'<p class="note">원본 레어 습득 + GⅠ 3승 후 한 진화 분기를 선택합니다.</p>'}</div>`}
function skillOutfitSourcesHTML(id){
 const renderSources=(title,outfits)=>outfits.length?`<section><h3 class="subheading">${title} · ${outfits.length}종</h3><div class="skill-outfit-sources">${outfits.map(o=>button(image(o,'avatar')+`<span><b>${esc(o.characterKo)}</b><small>${esc(o.ko)}</small></span>`,'dexItem',`data-kind="outfits" data-id="${o.gameId}"`,'small')).join('')}</div></section>`:'';
 const builtin=DB.outfits.filter(o=>[...(o.nativeSkills||[]),...(o.goldSkills||[]),...(o.uniqueSkills||[]),...(o.evolutionSkills||[]).flatMap(e=>[e.old,e.new])].includes(id));
 const inherited=DB.outfits.filter(o=>(o.uniqueSkills||[]).some(skill=>E.skills.get(skill)?.inherited===id));
 return renderSources('내장 스킬 보유 의상',builtin)+renderSources('계승기 원본 우마무스메',inherited);
}
function skillSourcesHTML(id,ownedOnly=false){const all=E.skillSources(id),owns=c=>(S.supports[c.gameId]||0)>0||E.own(S).some(u=>(u.supportCards||[]).some(x=>x.card===c.gameId)),cards=ownedOnly?all.filter(owns):all,skill=E.skills.get(Number(id));return `<section id="skillSourcesPanel"><h3 class="subheading">획득 가능한 서포트 카드 · ${cards.length}종</h3><div class="tabs skill-source-filters">${button('전체 카드','skillSourcesFilter26',`data-id="${id}" data-owned="0"`,ownedOnly?'small':'small active')}${button('보유 카드만','skillSourcesFilter26',`data-id="${id}" data-owned="1"`,ownedOnly?'small active':'small')}</div><p class="note">보유 카드에는 미장착 카드와 현재 소속 우마무스메에 장착한 카드를 포함합니다. 상위 스킬을 제공하는 카드로 하위 노말도 해금할 수 있습니다.</p>${cards.length?`<div class="skill-source-grid">${cards.map(c=>{const equipped=E.own(S).some(u=>(u.supportCards||[]).some(x=>x.card===c.gameId)),direct=c.skills.includes(Number(id));return `<button class="skill-source-card" data-action="support" data-id="${c.gameId}">${image(c,'avatar')}<span><b>${esc(c.koCharacter)} · ${c.rarity}</b>${supportTypeBadge(c)}<small>${esc(c.ko)}</small><small>${direct?'직접 해금':'상위 스킬로 하위 노말 해금'} · 미장착 ${S.supports[c.gameId]||0}장${equipped?' · 소속 장착 중':''}</small></span></button>`}).join('')}</div>`:empty(ownedOnly?'이 스킬을 제공하는 보유 카드가 없습니다.':skill?.rarity===6?'진화기는 해당 의상의 원본 레어를 진화해 획득합니다.':'현재 등록된 제공 서포트 카드가 없습니다.')}</section>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="skillSourcesFilter26"]');if(!b||b.disabled||busy)return;const panel=$('#skillSourcesPanel');if(panel)panel.outerHTML=skillSourcesHTML(Number(b.dataset.id),b.dataset.owned==='1')});
function auctionReportHTML(r){const rows=r.auctions||E.reportAuctions(S,r);if(!rows.length)return '';return `<section class="auction-report"><h3>스카우트 경매 결과 · ${rows.length}건</h3>${rows.map(a=>`<article><div><b>${esc(a.kind)} · ${esc(a.name)}</b><small>입찰 ${money(a.bid)} · 확률 ${(a.chance*100).toFixed(1)}%</small></div><div>${chip(a.won?'낙찰 · 확보':'유찰 · 전액 반환',a.won?'gold':'')}<b>${a.won?'추가 지출 없음':'수입 +'+money(a.bid)}</b></div></article>`).join('')}</section>`}

document.addEventListener('change',e=>{if(e.target.id==='financeRange'){financeRange=Number(e.target.value);render()}});

function processTurn(state){if(typeof Worker==='undefined'){E.advance(state);return Promise.resolve(state)}return new Promise((resolve,reject)=>{const worker=new Worker('turn-worker.js');worker.onmessage=e=>{if(e.data.progress){const b=document.querySelector('[data-action="advance"]');if(b)b.textContent='경기 처리 '+e.data.progress+'회…';return}worker.terminate();if(e.data.error)reject(new Error(e.data.error));else resolve(e.data.state)};worker.onerror=e=>{worker.terminate();reject(new Error(e.message||'시즌 계산을 완료하지 못했습니다.'))};worker.postMessage({state,db:DB})})}
document.addEventListener('click',e=>{if(busy&&e.target.closest('[data-action]')){e.preventDefault();e.stopImmediatePropagation();toast('시즌을 계산하고 있습니다. 완료 후 이용하세요.')}},true);
function noviceReportHTML(r){const rows=(r.retired||[]).map(id=>S.runners.find(u=>u.id===id)).filter(u=>u?.noviceFailed);return rows.length?`<section class="novice-failed"><h3>주니어 출전 자격 심사</h3>${rows.map(u=>`<p><b>${esc(name(u))}</b> · 9월 전반까지 신마전·미승리전 첫 승 미달 → 주니어 은퇴</p>`).join('')}<p>이후 모든 레이스 참가 불가 · 인자를 남기지 않습니다.</p></section>`:''}

function courseCatalogueHTML(){const all=E.courseCatalogue(),tracks=[...new Set(all.map(c=>c.raceTrackId))],q=search.toLowerCase();return `<p class="note">${tracks.length}개 경기장 · ${all.length}개 코스. 코스 그림과 구간·경사, 개별 각질의 스킬 조건을 확인합니다.</p><div class="course-grid">${tracks.map(id=>({id,rows:all.filter(c=>c.raceTrackId===id)})).filter(({rows})=>rows.some(c=>[c.name,c.distance,c.surface===1?'잔디':'더트'].join(' ').toLowerCase().includes(q))).map(({id,rows})=>`<article class="course-card">${courseMapHTML(rows.find(c=>c.surface===1&&c.distance===2000)||rows[0],true)}<div><h3>${esc(rows[0].name)}</h3><p>${Math.min(...rows.map(c=>c.distance))}–${Math.max(...rows.map(c=>c.distance))}m · ${rows.length}개 코스</p>${button('코스 · 스킬 분석','course','data-id="'+id+'"','primary small')}</div></article>`).join('')}</div>`}
function courseMapHTML(c,compact=false){const A=UmaRaceAnalysis,path=A.coursePath(c,c.distance,c.turn),xs=path.map(p=>p.x),ys=path.map(p=>p.y),loX=Math.min(...xs),loY=Math.min(...ys),w=Math.max(...xs)-loX||1,h=Math.max(...ys)-loY||1,scale=Math.min(770/w,165/h),X=p=>75+(770-w*scale)/2+(p.x-loX)*scale,Y=p=>50+(165-h*scale)/2+(p.y-loY)*scale,poly=ps=>ps.map(p=>`${X(p)},${Y(p)}`).join(' '),bounds=[0,c.distance/6,c.distance*2/3,c.distance*5/6,c.distance],colors=['#75aabd','#6a9e80','#d3ae67','#bb7d74'],goal=path.at(-1),heights=A.elevation(c,c.distance),minH=Math.min(...heights.map(p=>p.height)),maxH=Math.max(...heights.map(p=>p.height)),heightLine=heights.map(p=>`${55+p.m/c.distance*810},${65-(p.height-minH)/(maxH-minH||1)*45}`).join(' ');return `<div class="course-illustration ${compact?'compact':''}"><svg class="course-map" viewBox="0 0 920 270" role="img" aria-label="${esc(c.name)} ${c.distance}m 코스 그림"><rect width="920" height="270" rx="12" fill="#eef3e7"/><polyline points="${poly(path)}" fill="none" stroke="#bbc9b3" stroke-width="28" stroke-linecap="round" stroke-linejoin="round"/>${colors.map((color,i)=>`<polyline points="${poly(path.filter(p=>p.m>=bounds[i]&&p.m<=bounds[i+1]))}" fill="none" stroke="${color}" stroke-width="20" stroke-linecap="round" stroke-linejoin="round"/>`).join('')}${c.corners.map((corner,i)=>{const q=A.pathPoint(path,corner.start+corner.length/2);return `<g><circle cx="${X(q)}" cy="${Y(q)}" r="11" fill="#eff4e5" stroke="#7c9274"/><text x="${X(q)}" y="${Y(q)+4}" text-anchor="middle">${i+1}</text></g>`}).join('')}<circle cx="${X(path[0])}" cy="${Y(path[0])}" r="7" fill="#2f5946"/><text x="${Math.min(820,X(path[0])+12)}" y="${Y(path[0])-15}">START</text><circle cx="${X(goal)}" cy="${Y(goal)}" r="7" fill="#a75f4f"/><text x="${Math.min(820,X(goal)+12)}" y="${Y(goal)+24}">GOAL</text><text x="30" y="250">${esc(c.name)} · ${c.surface===2?'더트':'잔디'} ${c.distance}m · ${direction({direction:c.turn})}</text></svg>${compact?'':`<div class="course-phase-legend">${colors.map((color,i)=>`<span><i style="background:${color}"></i>${['초반','중반','종반','최종반'][i]} ${Math.round(bounds[i])}m</span>`).join('')}</div><svg class="course-elevation" viewBox="0 0 920 95" role="img" aria-label="거리별 경사와 고도 변화"><line x1="55" x2="865" y1="68" y2="68" stroke="#c6d4bc"/><polyline points="${heightLine}" fill="none" stroke="#6e8f66" stroke-width="2"/>${c.slopes.map(q=>`<rect x="${55+q.start/c.distance*810}" y="72" width="${q.length/c.distance*810}" height="5" fill="${q.slope>0?'#be8a75':'#75aabd'}"/><text x="${55+(q.start+q.length/2)/c.distance*810}" y="91" text-anchor="middle">${q.slope>0?'+':''}${q.slope}%</text>`).join('')}<text x="5" y="22">고도</text><text x="870" y="72">${c.distance}m</text></svg><p class="note">직선·코너·경사 데이터를 본떠 그린 코스 그림입니다. 인물·팀 포지션 배치는 포함하지 않습니다.</p>`}</div>`}
function courseRaceSchedule(trackId,course){
  const races=E.raceCatalogue(S).map((race,index)=>({race,index}))
    .filter(({race})=>race.trackId===trackId);
  const rows=races.map(({race:r,index})=>{
    const matches=String(E.courseFor(r).id)===String(course.id);
    const timing=Math.floor(r.turn/2)+1+'월 '+(r.turn%2?'후반':'전반');
    return `<button class="course-schedule-row" data-action="raceDexItem" data-index="${index}">
      <span>${timing}</span><strong>${esc(r.name)}</strong>
      <small>${esc(E.gradeName(r))} · ${r.terrain===2?'더트':'잔디'} ${r.distance}m${matches?' · 선택 코스':''}</small>
    </button>`;
  }).join('');
  return `<h3 class="subheading">이 경기장에서 열리는 레이스 · ${races.length}개</h3>
    ${rows?`<div class="course-schedule">${rows}</div>`:empty('이 경기장의 등록된 레이스가 없습니다.')}`;
}
function courseRecommendationsHTML(profile){
  const {runners,factors}=E.courseRecommendations(profile);
  const score=n=>n.toFixed(2);
  const skill=x=>`${skillButton(x.id)} <small>${score(x.score)}점${x.conditional?' · 조건부':''}${x.baseId&&x.baseId!==x.id?' · 진화 전 '+score(x.baseScore)+'점':''}</small>`;
  return `<h3 class="subheading">코스 추천 · ${styleNames[profile.options.style]}</h3>
    <p class="note">모든 의상을 고유기와 내장 진화기의 코스 유효 점수 합계로 정렬합니다. 같은 내장 스킬의 진화 분기는 최고 점수 하나를 반영합니다. 유효 점수가 있는 의상만 표시하며, 계승기 1티어는 양수 점수 후보 중 상위 10%입니다. 순위 등 미확정 발동 조건은 감점합니다.</p>
    <details class="course-tier"><summary>유효 우마무스메 · ${runners.length}개 의상</summary><div class="course-recommendations course-effective-runners">${runners.map(({outfit,score:rating,skills},index)=>`<article><header><small>${index+1}위</small>${image(outfit,'avatar')}<div><b>${esc(outfit.characterKo)}</b><br><small>${esc(outfit.ko)}</small></div><strong>합계 ${score(rating)}점</strong></header>${skills.map(x=>`<div class="course-recommendation-skill">${skill(x)}</div>`).join('')||'<small>유효 점수를 얻은 스킬이 없습니다.</small>'}</article>`).join('')||empty('유효 점수가 있는 의상이 없습니다.')}</div></details>
    <details class="course-tier" open><summary>1티어 인자 계승기 · ${factors.length}개</summary><div class="course-recommendations">${factors.map(({skill:x,sources})=>`<article><div class="course-recommendation-skill">${skill(x)}</div><div class="course-factor-sources">${sources.map(o=>`<span>${image(o,'avatar')}<small>${esc(o.characterKo+' ('+o.ko+')')}</small></span>`).join('')}</div></article>`).join('')||empty('추천 기준을 충족하는 계승기가 없습니다.')}</div></details>`;
}
function openCourse(trackId,courseId=null){const rows=E.courseCatalogue().filter(c=>c.raceTrackId===trackId),c=rows.find(c=>c.id===String(courseId||guideCourse))||rows.find(c=>c.distance===2000&&c.surface===1)||rows[0];if(!c)return;guideTrack=trackId;guideCourse=c.id;const p=E.courseSkillProfile(c,guideOptions),last=c.straights.at(-1),skills=items=>items.map(x=>`<article class="course-skill-row"><div>${skillButton(x.id)}<small>${x.from!=null?`${x.from}–${x.to}m · ${x.duration}초`:'시작 시 패시브'}${x.heal?' · HP '+(x.heal*100).toFixed(1)+'% 회복':''}${x.conditional?' · 추가 발동 조건 필요':''}</small></div><details><summary>조건·판정</summary><p>${x.effects?x.effects.map(e=>([null,'스피드','스태미나','파워','근성','지능'][e.type]||'전 능력')+' +'+e.value).join(' · '):'효과·지속시간·종반 가속 구간을 비교한 조건부 적합도입니다.'}</p>${x.conditions.map(k=>`<code>${esc(k)}</code>`).join('<br>')}${x.unknown?.length?'<p>추가 조건: '+esc(x.unknown.join(', '))+'</p>':''}</details></article>`).join('')||empty('선택한 조건에 맞는 후보 없음');showModal(`<span class="eyebrow">COURSE ATLAS · SOLO SKILL FIT</span><h2 class="modal-title">${esc(c.name)} · ${c.surface===2?'더트':'잔디'} ${c.distance}m</h2><div class="course-controls"><label>코스<select id="guideCourse">${rows.map(r=>`<option value="${r.id}" ${r.id===c.id?'selected':''}>${r.surface===2?'더트':'잔디'} ${r.distance}m · ${direction({direction:r.turn})} · #${r.id}</option>`).join('')}</select></label>${[['style','각질',styleNames],['season','계절',['봄','여름','가을','겨울']],['weather','날씨',['맑음','흐림','비','눈']],['ground','마장',['양호','다습','포화','불량']],['time','시간',['아침','낮','저녁','야간']]].map(([key,label,opts])=>`<label>${label}<select data-guide-option="${key}">${opts.map((n,i)=>{const v=key==='style'?i:i+1;return `<option value="${v}" ${guideOptions[key]===v?'selected':''}>${n}</option>`}).join('')}</select></label>`).join('')}${button('CM22 코스·기상 참고','cmCoursePreset','','small')}</div>${courseMapHTML(c)}${courseRaceSchedule(trackId,c)}<div class="course-facts">${[['종반 진입',Math.round(c.distance*2/3)+'m'],['최종 직선',last?Math.round(last.end-last.start)+'m':'자료 없음'],['코너',c.corners.length+'구간'],['경사',c.slopes.map(s=>(s.slope>0?'+':'')+s.slope+'%').join(' / ')||'평지']].map(([k,v])=>`<div><small>${k}</small><b>${v}</b></div>`).join('')}</div><div class="note strong-note">FM 개별 주자 코스 적합도 · 추정 티어<br>일반·레어 스킬의 효과량/SP, 발동 가능 구간, 종반 초입 가속 구간을 비교합니다. 추가 조건이 있는 스킬은 조건부입니다. 실제 발동률·승률을 뜻하지 않으며, 팀 구성·디버퍼 역할·팀 승률은 평가에 넣지 않습니다.</div>${courseRecommendationsHTML(p)}<h3 class="subheading">조건에 맞는 패시브 · ${p.passive.length}개</h3><details><summary>각질·계절·날씨·마장·방향·경기장 조건 확인</summary>${skills(p.passive)}</details><h3 class="subheading">유효 스킬 티어 · ${styleNames[guideOptions.style]}</h3>${['S','A','B','C'].map(t=>{const rows=p.ranked.filter(x=>x.tier===t);return `<details class="course-tier"><summary><b>${t}</b> ${t==='S'?'우선 검토':t==='A'?'유효 후보':t==='B'?'조건 확인':'제한적 활용'} · ${rows.length}개</summary>${skills(rows)}</details>`}).join('')}<details class="course-tier"><summary>회복 후보 · ${p.recovery.length}개</summary><p class="note">스태미나·거리·흥분·경합에 따라 필요량이 달라집니다. 무조건적인 우열이 아닙니다.</p>${skills(p.recovery)}</details><details><summary>참고 자료·평가 범위</summary><p><a href="https://uma.moe/tools/skill-explorer" target="_blank" rel="noopener">uma.moe Skill Explorer</a>: 개별 각질, 발동 지점, SP, 단독 효과, 발동률의 구분을 참고했습니다. 이 도감의 티어는 FM 계산용 추정이며 해당 사이트의 승률 추정치를 복제하지 않습니다.</p><p><a href="https://uma.moe/competitive/cm-data?tab=introduction&amp;snapshot=cm22-2026-11-01" target="_blank" rel="noopener">CM22 조건 참고</a>: 도쿄 더트 1600m·겨울·눈·포화 마장. 3인 팀 포지션·편성·팀 승률과 원작 고정 스탯은 가져오지 않습니다.</p><p>고유·진화기는 의상별 스킬 상세에서 확인하세요. 순위·추월·HP·자신의 스킬 발동 수 등 추가 조건을 만족해야 실제 경주에서 발동합니다.</p></details>`)}
function titleCatalogueHTML(){const q=search.toLowerCase(),rows=E.titleCatalogue(S).map((t,i)=>({...t,index:i})).filter(t=>[t.name,t.kind,t.requirement].join(' ').toLowerCase().includes(q)).sort((a,b)=>['SSR','SR','R'].indexOf(a.grade)-['SSR','SR','R'].indexOf(b.grade));return `<p class="note">GⅠ 우승 · 네 종류의 삼관 · JRA 수상 · 현창 우마무스메. 소속 우마무스메의 획득 여부를 함께 표시합니다.</p><div class="title-grid">${rows.map(t=>{const owners=S.runners.filter(u=>u.team===0&&(u.titles||[]).some(a=>a.name.includes(t.name.replace('JRA 연도별 ',''))));return `<button class="title-card ${owners.length?'owned':''}" data-action="titleInfo" data-id="${t.index}"><small>${titleRankBadge(t.grade)} ${esc(t.kind)}</small><b>${esc(t.name)}</b><span>${esc(t.requirement)}</span><em>${owners.length?'획득 · '+owners.map(name).join(', '):'미획득'}</em></button>`}).join('')}</div>`}
function openTitle(index){const t=E.titleCatalogue(S)[index];if(!t)return;showModal(`<span class="eyebrow">TITLE COLLECTION · ${esc(t.kind)}</span><h2 class="modal-title">${titleRankBadge(t.grade)} ${esc(t.name)}</h2><div class="note strong-note">${esc(t.requirement)}</div>${t.kind==='명예'?'<p>게임의 현창 우마무스메 선정 기준입니다. 플레이어 직접 은퇴와 NPC 자동 은퇴를 함께 심사해 매년 최대 1명을 선정합니다. 플레이어 자동 은퇴·주니어 자격 미달 은퇴는 제외합니다. 후보 기간은 해당 연도 1월 전반부터 12월 후반까지이며, 12월 후반 종료 후 JRA 시상식에서 발표합니다.</p>':''}<h3 class="subheading">소속 우마무스메 획득 기록</h3>${S.runners.filter(u=>u.team===0).map(u=>`<div class="line-item"><b>${esc(name(u))}</b><span>${(u.titles||[]).filter(a=>a.name.includes(t.name.replace('JRA 연도별 ',''))).map(a=>esc(a.name)).join(' / ')||'미획득'}</span></div>`).join('')}`)}
document.addEventListener('change',e=>{if(e.target.id==='guideCourse')openCourse(guideTrack,e.target.value);else if(e.target.dataset.guideOption){guideOptions[e.target.dataset.guideOption]=Number(e.target.value);openCourse(guideTrack,guideCourse)}});

function qualificationHTML(u){if(u.noviceFailed)return '<p class="qualification-note failed">첫 승 자격 미달 · 주니어 은퇴 · 인자 없음</p>';if(u.status==='undebuted')return '<p class="qualification-note">6월 전반 개별 신마전 준비 · 상대는 전원 모브</p>';return `<p class="qualification-note ${E.juniorQualified(u)?'':'failed'}">${E.juniorQualified(u)?'첫 승 자격 통과 · 정규 레이스 출전 가능':'첫 승 자격 미달 · 미승리전만 출전 / 9월 전반 종료까지 1착 필요'}</p>`}
function raceRatingHTML(result){const rows=result.rows.filter(r=>r.team===0&&r.rating!=null);return rows.length?`<section class="qualification-note"><h3>실시간 평가 갱신</h3>${rows.map(r=>`<p>${esc(r.name)} · 경기 평가 ${r.performance} / 현재 ${r.rating} Pt</p>`).join('')}<small>상위 40% 밖의 착순은 음수 평가. 매 경기 평가를 합산합니다. 호성적은 가산되고 부진한 성적은 감점됩니다.</small></section>`:''}

function dexFiltersHTML(){if(!['outfits','skills','supports'].includes(dexTab))return '';const select=(key,label,options)=>`<label>${label}<select data-dex-filter="${key}"><option value="all">전체</option>${options.map(([v,n])=>`<option value="${v}" ${String(dexFilters[key])===String(v)?'selected':''}>${n}</option>`).join('')}</select></label>`;return `<div class="dex-filters">${select('style','각질',styleNames.map((n,i)=>[i,n]))}${select('distance','거리',['단거리','마일','중거리','장거리'].map((n,i)=>[i,n]))}${select('surface','주로',[[1,'잔디'],[2,'더트']])}${dexTab==='outfits'?`<label>최소 적성<select data-dex-filter="apt">${[[4,'C 이상'],[5,'B 이상'],[6,'A 이상']].map(([v,n])=>`<option value="${v}" ${Number(dexFilters.apt)===v?'selected':''}>${n}</option>`).join('')}</select></label>`:`${select('rarity','등급',dexTab==='supports'?[['SSR','SSR'],['SR','SR'],['R','R']]:[[1,'노말'],[2,'레어'],['unique','고유'],[6,'진화']])}${select('effect','효과',['속도','가속','회복','패시브','디버프','스타트','시야·진로'].map(n=>[n,n]))}<label class="dex-generic"><input type="checkbox" data-dex-filter="generic" ${dexFilters.generic?'checked':''}>범용 스킬 포함</label>`}${button('분류 초기화','dexReset','','small')}</div>`}
document.addEventListener('change',e=>{const key=e.target.dataset.dexFilter;if(!key)return;dexFilters[key]=key==='generic'?e.target.checked:e.target.value;dexLimit=60;$('#dexResults').innerHTML=dexResultsHTML()});

function updateSupportEquip26(){const select=$('#supportRunner'),b=$('#modalBody [data-action="useSupport"]'),note=$('#supportEquipReason26');if(!select||!b||!note)return;const u=S.runners.find(u=>u.id===Number(select.value)),cid=Number(b.dataset.id),slot=u&&E.supportSlots(S,u),duplicate=E.hasSupportCard(u,cid);let why=!u?'장착할 우마무스메가 없습니다.':duplicate?'이미 동일한 서포트 카드를 장착했습니다. 같은 캐릭터의 다른 카드는 장착할 수 있습니다.':!(S.supports[cid]>0)?'미장착 보유 카드가 없습니다.':!slot.window||slot.used>=slot.limit||slot.total>=6?'이번 기간의 서포트 장착 슬롯이 가득 찼습니다.':u.trainingBoard?.at===E.abs(S)?'이번 턴 훈련 배치를 확인했습니다. 다음 턴부터 장착할 수 있습니다.':'';b.disabled=!!why;b.textContent=duplicate?'동일 카드 장착됨':'영구 장착';note.textContent=why;note.classList.toggle('race-entry-reason',duplicate)}
document.addEventListener('change',e=>{if(e.target.id==='supportRunner')updateSupportEquip26()});
